ARCHIVOS = {
    'supabase/migrations/20261106000001_tablas.sql': '-- =====================================================================\n-- PASO 1 · Tablas\n-- EcoResiduos del Llano S.A.S. — Red logística de residuos agropecuarios\n--\n-- Tablas principales (las que pide el enunciado):\n--   * escenarios  : id, nombre, fecha y parametros_entrada (oferta, demanda, costos)\n--   * resultados  : id, escenario_id, algoritmo_utilizado (\'Exacto\' | \'Genético\'),\n--                   costo_total, tiempo_ejecucion_ms, gap_desviacion, matriz_flujos_json\n--\n-- Tablas de apoyo (detalle de la red y del análisis de sensibilidad):\n--   * agroempresas, plantas, rutas : la red G = (V, E) que se edita desde la web\n--   * precios_sombra               : duales uᵢ / vⱼ de cada resultado exacto\n--\n-- escenarios.parametros_entrada se calcula a partir de agroempresas, plantas\n-- y rutas (función refrescar_parametros_entrada, paso 3); nunca se edita a mano.\n-- =====================================================================\n\ncreate extension if not exists pgcrypto;  -- gen_random_uuid() (ya viene en Supabase)\n\n-- ---------------------------------------------------------------------\n-- escenarios\n-- ---------------------------------------------------------------------\ncreate table if not exists public.escenarios (\n    id                              uuid primary key default gen_random_uuid(),\n    nombre                          text not null unique\n                                    check (length(trim(nombre)) > 0),\n    fecha                           timestamptz not null default now(),\n    descripcion                     text,\n    -- {"fuentes": [...], "plantas": [...], "oferta": [...], "demanda": [...],\n    --  "costos": [[...]], "distancias_km": [[...]], "costo_transporte_km_ton": 1200, ...}\n    parametros_entrada              jsonb not null default \'{}\'::jsonb,\n    es_base                         boolean not null default false,\n    costo_transporte_km_ton         numeric not null default 1200\n                                    check (costo_transporte_km_ton >= 0),\n    factor_penalizacion_oferta      numeric not null default 1000\n                                    check (factor_penalizacion_oferta >= 0),\n    factor_penalizacion_capacidad   numeric not null default 1000\n                                    check (factor_penalizacion_capacidad >= 0),\n    escenario_origen_id             uuid references public.escenarios(id) on delete set null,\n    variaciones                     jsonb not null default \'{}\'::jsonb,\n    actualizado_en                  timestamptz not null default now()\n);\n\ncomment on column public.escenarios.fecha is \'Fecha de creación del escenario.\';\ncomment on column public.escenarios.parametros_entrada is\n    \'Parámetros de entrada del modelo: oferta, demanda (capacidad) y matriz de costos cᵢⱼ. Se calcula automáticamente.\';\ncomment on column public.escenarios.variaciones is\n    \'Variaciones aplicadas si el escenario es derivado, p. ej. {"variacion_costos_pct": 10}.\';\n\ncreate unique index if not exists escenarios_un_solo_base\n    on public.escenarios (es_base) where es_base;\n\n-- ---------------------------------------------------------------------\n-- agroempresas (fuentes, nodos de oferta)\n-- ---------------------------------------------------------------------\ncreate table if not exists public.agroempresas (\n    id              uuid primary key default gen_random_uuid(),\n    escenario_id    uuid not null references public.escenarios(id) on delete cascade,\n    codigo          text not null check (length(trim(codigo)) > 0),   -- \'E01\'\n    nombre          text not null check (length(trim(nombre)) > 0),\n    municipio       text,\n    sector          text,\n    oferta_ton_sem  numeric not null check (oferta_ton_sem >= 0),     -- Oᵢ\n    orden           integer not null check (orden >= 0),              -- fila i\n    unique (escenario_id, codigo),\n    unique (escenario_id, orden),\n    unique (id, escenario_id)\n);\n\n-- ---------------------------------------------------------------------\n-- plantas (destinos, nodos de demanda)\n-- ---------------------------------------------------------------------\ncreate table if not exists public.plantas (\n    id                          uuid primary key default gen_random_uuid(),\n    escenario_id                uuid not null references public.escenarios(id) on delete cascade,\n    codigo                      text not null check (length(trim(codigo)) > 0),  -- \'P1\'\n    nombre                      text not null check (length(trim(nombre)) > 0),\n    municipio                   text,\n    capacidad_maxima_ton_sem    numeric not null check (capacidad_maxima_ton_sem >= 0),  -- Dⱼ\n    costo_operativo_ton         numeric not null check (costo_operativo_ton >= 0),       -- cⱼᵒᵖ\n    orden                       integer not null check (orden >= 0),                     -- columna j\n    unique (escenario_id, codigo),\n    unique (escenario_id, orden),\n    unique (id, escenario_id)\n);\n\n-- ---------------------------------------------------------------------\n-- rutas (arcos (i,j) ∈ E)\n-- ---------------------------------------------------------------------\ncreate table if not exists public.rutas (\n    escenario_id    uuid not null references public.escenarios(id) on delete cascade,\n    agroempresa_id  uuid not null,\n    planta_id       uuid not null,\n    distancia_km    numeric not null check (distancia_km >= 0),   -- dᵢⱼ\n    habilitada      boolean not null default true,\n    primary key (agroempresa_id, planta_id),\n    foreign key (agroempresa_id, escenario_id)\n        references public.agroempresas (id, escenario_id) on delete cascade,\n    foreign key (planta_id, escenario_id)\n        references public.plantas (id, escenario_id) on delete cascade\n);\n\ncreate index if not exists rutas_escenario_idx on public.rutas (escenario_id);\n\n-- ---------------------------------------------------------------------\n-- resultados (una fila por cada ejecución del sistema)\n--\n-- matriz_flujos_json:\n--   {"agroempresas": ["E01", ...], "plantas": ["P1", ...],\n--    "toneladas": [[x11, x12, ...], ...]}          -- xᵢⱼ en t/semana\n--\n-- gap_desviacion (%) = (Z_AG − Z_exacto) / Z_exacto × 100\n--   * \'Exacto\'  -> 0\n--   * \'Genético\'-> se calcula solo contra el último resultado exacto del\n--                  mismo escenario (trigger del paso 3). Queda NULL si aún\n--                  no hay uno exacto y se completa cuando se guarde.\n-- ---------------------------------------------------------------------\ncreate table if not exists public.resultados (\n    id                      uuid primary key default gen_random_uuid(),\n    escenario_id            uuid not null references public.escenarios(id) on delete cascade,\n    algoritmo_utilizado     text not null check (algoritmo_utilizado in (\'Exacto\', \'Genético\')),\n    costo_total             numeric not null check (costo_total >= 0),        -- Z\n    tiempo_ejecucion_ms     double precision not null check (tiempo_ejecucion_ms >= 0),\n    gap_desviacion          numeric,                                         -- %\n    matriz_flujos_json      jsonb not null,\n    -- campos adicionales útiles para el informe\n    costo_transporte        numeric,\n    costo_operativo         numeric,\n    factible                boolean,\n    parametros_algoritmo    jsonb not null default \'{}\'::jsonb,   -- población, generaciones, solver...\n    historial_fitness       jsonb,                                -- convergencia del AG\n    resultado_exacto_id     uuid references public.resultados(id) on delete set null,  -- contra cuál se midió el gap\n    fecha                   timestamptz not null default now()\n);\n\ncomment on column public.resultados.gap_desviacion is\n    \'Gap (%) = (Z_AG − Z_exacto) / Z_exacto × 100, contra el último resultado exacto del escenario.\';\n\ncreate index if not exists resultados_escenario_idx\n    on public.resultados (escenario_id, algoritmo_utilizado, fecha desc);\n\n-- ---------------------------------------------------------------------\n-- precios_sombra (duales de un resultado exacto)\n-- ---------------------------------------------------------------------\ncreate table if not exists public.precios_sombra (\n    resultado_id    uuid not null references public.resultados(id) on delete cascade,\n    tipo            text not null check (tipo in (\'oferta\', \'capacidad\')),\n    nodo_codigo     text not null,\n    valor_dual      numeric not null,\n    holgura         numeric,\n    rango_inferior  numeric,\n    rango_superior  numeric,\n    primary key (resultado_id, tipo, nodo_codigo)\n);\n\n-- ---------------------------------------------------------------------\n-- actualizado_en automático\n-- ---------------------------------------------------------------------\ncreate or replace function public.tg_actualizado_en()\nreturns trigger language plpgsql\nset search_path = public\nas $$\nbegin\n    new.actualizado_en := now();\n    return new;\nend;\n$$;\n\ndrop trigger if exists escenarios_actualizado_en on public.escenarios;\ncreate trigger escenarios_actualizado_en\n    before update on public.escenarios\n    for each row execute function public.tg_actualizado_en();\n',
    'supabase/migrations/20261106000002_vistas.sql': "-- =====================================================================\n-- PASO 2 · Vistas de consulta\n-- =====================================================================\n\n-- ---------------------------------------------------------------------\n-- Matriz de costos unitarios: cᵢⱼ = cᵤ·dᵢⱼ + cⱼᵒᵖ   [COP/ton]\n-- ---------------------------------------------------------------------\ncreate or replace view public.v_matriz_costos\nwith (security_invoker = true) as\nselect\n    r.escenario_id,\n    a.codigo                                    as agroempresa_codigo,\n    p.codigo                                    as planta_codigo,\n    a.orden                                     as fila,\n    p.orden                                     as columna,\n    r.distancia_km,\n    e.costo_transporte_km_ton,\n    p.costo_operativo_ton,\n    e.costo_transporte_km_ton * r.distancia_km  as costo_transporte_ton,\n    e.costo_transporte_km_ton * r.distancia_km\n        + p.costo_operativo_ton                 as costo_unitario,\n    r.habilitada\nfrom public.rutas r\njoin public.escenarios   e on e.id = r.escenario_id\njoin public.agroempresas a on a.id = r.agroempresa_id\njoin public.plantas      p on p.id = r.planta_id;\n\n-- ---------------------------------------------------------------------\n-- Historial de escenarios con tamaño de la red, balance y nº de resultados\n-- ---------------------------------------------------------------------\ncreate or replace view public.v_resumen_escenarios\nwith (security_invoker = true) as\nselect\n    e.id,\n    e.nombre,\n    e.fecha,\n    e.descripcion,\n    e.es_base,\n    e.costo_transporte_km_ton,\n    coalesce(a.n, 0)                               as num_agroempresas,\n    coalesce(p.n, 0)                               as num_plantas,\n    coalesce(r.n, 0)                               as num_rutas_habilitadas,\n    coalesce(a.total, 0)                           as oferta_total,\n    coalesce(p.total, 0)                           as capacidad_total,\n    coalesce(p.total, 0) - coalesce(a.total, 0)    as holgura_capacidad,\n    case\n        when coalesce(a.total, 0) = coalesce(p.total, 0) then 'balanceada'\n        when coalesce(a.total, 0) < coalesce(p.total, 0) then 'capacidad_sobrante'\n        else 'oferta_excedente'\n    end                                            as estado_balance,\n    coalesce(res.n, 0)                             as num_resultados,\n    res.ultima                                     as fecha_ultimo_resultado,\n    e.escenario_origen_id,\n    e.variaciones,\n    e.actualizado_en\nfrom public.escenarios e\nleft join (select escenario_id, count(*) n, sum(oferta_ton_sem) total\n           from public.agroempresas group by escenario_id) a on a.escenario_id = e.id\nleft join (select escenario_id, count(*) n, sum(capacidad_maxima_ton_sem) total\n           from public.plantas group by escenario_id) p on p.escenario_id = e.id\nleft join (select escenario_id, count(*) n\n           from public.rutas where habilitada group by escenario_id) r on r.escenario_id = e.id\nleft join (select escenario_id, count(*) n, max(fecha) ultima\n           from public.resultados group by escenario_id) res on res.escenario_id = e.id;\n\n-- ---------------------------------------------------------------------\n-- Análisis comparativo: último Exacto vs. último Genético de cada escenario\n-- ---------------------------------------------------------------------\ncreate or replace view public.v_historial_comparativo\nwith (security_invoker = true) as\nwith ultimo as (\n    select distinct on (escenario_id, algoritmo_utilizado) *\n    from public.resultados\n    order by escenario_id, algoritmo_utilizado, fecha desc\n)\nselect\n    e.id                        as escenario_id,\n    e.nombre                    as escenario,\n    e.fecha                     as fecha_escenario,\n    ex.id                       as resultado_exacto_id,\n    ag.id                       as resultado_genetico_id,\n    ex.costo_total              as costo_exacto,\n    ag.costo_total              as costo_genetico,\n    case when ex.costo_total > 0\n         then (ag.costo_total - ex.costo_total) / ex.costo_total * 100\n    end                         as gap_desviacion,\n    ex.tiempo_ejecucion_ms      as tiempo_exacto_ms,\n    ag.tiempo_ejecucion_ms      as tiempo_genetico_ms,\n    ag.factible                 as genetico_factible,\n    ag.parametros_algoritmo     as parametros_ag,\n    greatest(ex.fecha, ag.fecha) as fecha_ultimo_resultado\nfrom public.escenarios e\nleft join ultimo ex on ex.escenario_id = e.id and ex.algoritmo_utilizado = 'Exacto'\nleft join ultimo ag on ag.escenario_id = e.id and ag.algoritmo_utilizado = 'Genético'\nwhere ex.id is not null or ag.id is not null;\n",
    'supabase/migrations/20261106000003_funciones.sql': '-- =====================================================================\n-- PASO 3 · Funciones y triggers\n--\n--   refrescar_parametros_entrada(id)  -> recalcula escenarios.parametros_entrada\n--   obtener_config_escenario(nombre)  -> jsonb con el MISMO formato de dataConfig.json\n--   guardar_config_escenario(...)     -> crea/reemplaza un escenario desde ese formato\n--   clonar_escenario(...)             -> copia para sensibilidad (HU4) o HU8\n--   trigger de resultados             -> normaliza el algoritmo, valida la matriz,\n--                                        desglosa el costo y calcula el gap\n-- =====================================================================\n\n-- ---------------------------------------------------------------------\n-- refrescar_parametros_entrada\n-- Construye: fuentes, plantas, oferta, demanda, costo_operativo,\n-- distancias_km, costos (cᵢⱼ), costo_transporte_km_ton, totales.\n-- ---------------------------------------------------------------------\ncreate or replace function public.refrescar_parametros_entrada(p_escenario uuid)\nreturns void\nlanguage plpgsql\nset search_path = public\nas $$\nbegin\n    update public.escenarios e\n    set parametros_entrada = jsonb_build_object(\n        \'fuentes\',  coalesce((select jsonb_agg(a.codigo order by a.orden)\n                              from public.agroempresas a where a.escenario_id = e.id), \'[]\'::jsonb),\n        \'plantas\',  coalesce((select jsonb_agg(p.codigo order by p.orden)\n                              from public.plantas p where p.escenario_id = e.id), \'[]\'::jsonb),\n        \'oferta\',   coalesce((select jsonb_agg(a.oferta_ton_sem order by a.orden)\n                              from public.agroempresas a where a.escenario_id = e.id), \'[]\'::jsonb),\n        \'demanda\',  coalesce((select jsonb_agg(p.capacidad_maxima_ton_sem order by p.orden)\n                              from public.plantas p where p.escenario_id = e.id), \'[]\'::jsonb),\n        \'costo_operativo\', coalesce((select jsonb_agg(p.costo_operativo_ton order by p.orden)\n                              from public.plantas p where p.escenario_id = e.id), \'[]\'::jsonb),\n        \'costo_transporte_km_ton\', e.costo_transporte_km_ton,\n        \'distancias_km\', coalesce((\n            select jsonb_agg(f.fila order by f.fila_i) from (\n                select mc.fila as fila_i, jsonb_agg(mc.distancia_km order by mc.columna) as fila\n                from public.v_matriz_costos mc where mc.escenario_id = e.id\n                group by mc.fila) f), \'[]\'::jsonb),\n        \'costos\', coalesce((\n            select jsonb_agg(f.fila order by f.fila_i) from (\n                select mc.fila as fila_i, jsonb_agg(mc.costo_unitario order by mc.columna) as fila\n                from public.v_matriz_costos mc where mc.escenario_id = e.id\n                group by mc.fila) f), \'[]\'::jsonb),\n        \'rutas_deshabilitadas\', coalesce((\n            select jsonb_agg(jsonb_build_array(mc.agroempresa_codigo, mc.planta_codigo)\n                             order by mc.fila, mc.columna)\n            from public.v_matriz_costos mc where mc.escenario_id = e.id and not mc.habilitada), \'[]\'::jsonb),\n        \'oferta_total\',    coalesce((select sum(a.oferta_ton_sem)\n                                     from public.agroempresas a where a.escenario_id = e.id), 0),\n        \'capacidad_total\', coalesce((select sum(p.capacidad_maxima_ton_sem)\n                                     from public.plantas p where p.escenario_id = e.id), 0),\n        \'unidades\', jsonb_build_object(\'oferta_demanda\', \'t/semana\', \'costos\', \'COP/t\',\n                                       \'distancias\', \'km\', \'costo_transporte\', \'COP/(km·t)\')\n    )\n    where e.id = p_escenario;\nend;\n$$;\n\n-- Mantener parametros_entrada al día si se edita la red desde el ORM o el Table Editor\ncreate or replace function public.tg_refrescar_parametros()\nreturns trigger\nlanguage plpgsql\nset search_path = public\nas $$\nbegin\n    if coalesce(current_setting(\'eco.sin_refresco\', true), \'\') = \'on\' then\n        return null;\n    end if;\n    if tg_op in (\'INSERT\', \'UPDATE\') then\n        perform public.refrescar_parametros_entrada(new.escenario_id);\n    end if;\n    if tg_op in (\'UPDATE\', \'DELETE\') and (tg_op = \'DELETE\' or old.escenario_id <> new.escenario_id) then\n        perform public.refrescar_parametros_entrada(old.escenario_id);\n    end if;\n    return null;\nend;\n$$;\n\ndrop trigger if exists agroempresas_refrescar on public.agroempresas;\ncreate trigger agroempresas_refrescar after insert or update or delete on public.agroempresas\n    for each row execute function public.tg_refrescar_parametros();\ndrop trigger if exists plantas_refrescar on public.plantas;\ncreate trigger plantas_refrescar after insert or update or delete on public.plantas\n    for each row execute function public.tg_refrescar_parametros();\ndrop trigger if exists rutas_refrescar on public.rutas;\ncreate trigger rutas_refrescar after insert or update or delete on public.rutas\n    for each row execute function public.tg_refrescar_parametros();\n\ncreate or replace function public.tg_escenario_cu()\nreturns trigger\nlanguage plpgsql\nset search_path = public\nas $$\nbegin\n    perform public.refrescar_parametros_entrada(new.id);\n    return null;\nend;\n$$;\n\ndrop trigger if exists escenarios_refrescar_cu on public.escenarios;\ncreate trigger escenarios_refrescar_cu after update of costo_transporte_km_ton on public.escenarios\n    for each row execute function public.tg_escenario_cu();\n\n-- ---------------------------------------------------------------------\n-- obtener_config_escenario: mismas claves que dataConfig.json\n-- (EvaluadorFitness lee la penalización de oferta en "factorPlanta"\n--  y la de capacidad en "factorDemanda")\n-- ---------------------------------------------------------------------\ncreate or replace function public.obtener_config_escenario(p_nombre text)\nreturns jsonb\nlanguage plpgsql stable\nset search_path = public\nas $$\ndeclare\n    e   public.escenarios%rowtype;\nbegin\n    select * into e from public.escenarios where nombre = p_nombre;\n    if not found then\n        raise exception \'No existe el escenario "%"\', p_nombre using errcode = \'P0002\';\n    end if;\n\n    return jsonb_build_object(\n        \'_meta\', jsonb_build_object(\n            \'escenario_id\',        e.id,\n            \'nombre\',              e.nombre,\n            \'fecha\',               e.fecha,\n            \'descripcion\',         e.descripcion,\n            \'es_base\',             e.es_base,\n            \'escenario_origen_id\', e.escenario_origen_id,\n            \'variaciones\',         e.variaciones,\n            \'fuente\',              \'base_de_datos\'\n        ),\n        \'parametros_globales\', jsonb_build_object(\n            \'costo_transporte_km_ton\', e.costo_transporte_km_ton\n        ),\n        \'penalizaciones\', jsonb_build_object(\n            \'factorPlanta\',  e.factor_penalizacion_oferta,\n            \'factorDemanda\', e.factor_penalizacion_capacidad\n        ),\n        \'plantas\', (\n            select coalesce(jsonb_agg(jsonb_build_object(\n                       \'id\',                       p.codigo,\n                       \'nombre\',                   p.nombre,\n                       \'municipio\',                p.municipio,\n                       \'capacidad_maxima_ton_sem\', p.capacidad_maxima_ton_sem,\n                       \'costo_operativo_ton\',      p.costo_operativo_ton\n                   ) order by p.orden), \'[]\'::jsonb)\n            from public.plantas p where p.escenario_id = e.id\n        ),\n        \'agroempresas\', (\n            select coalesce(jsonb_agg(jsonb_build_object(\n                       \'id\',             a.codigo,\n                       \'nombre\',         a.nombre,\n                       \'municipio\',      a.municipio,\n                       \'sector\',         a.sector,\n                       \'oferta_ton_sem\', a.oferta_ton_sem\n                   ) order by a.orden), \'[]\'::jsonb)\n            from public.agroempresas a where a.escenario_id = e.id\n        ),\n        \'matriz_distancias_km\', (\n            select coalesce(jsonb_object_agg(f.codigo, f.fila), \'{}\'::jsonb)\n            from (\n                select a.codigo, jsonb_object_agg(p.codigo, r.distancia_km) as fila\n                from public.rutas r\n                join public.agroempresas a on a.id = r.agroempresa_id\n                join public.plantas      p on p.id = r.planta_id\n                where r.escenario_id = e.id\n                group by a.codigo\n            ) f\n        ),\n        \'rutas_deshabilitadas\', e.parametros_entrada -> \'rutas_deshabilitadas\'\n    );\nend;\n$$;\n\n-- ---------------------------------------------------------------------\n-- guardar_config_escenario\n-- Recibe el formato de dataConfig.json. Exige distancia para cada pareja\n-- agroempresa-planta; una ruta se retira con\n--   "rutas_deshabilitadas": [["E01","P4"], ...].\n-- Con p_reemplazar = true sobrescribe la red (los resultados se conservan).\n-- ---------------------------------------------------------------------\ncreate or replace function public.guardar_config_escenario(\n    p_nombre       text,\n    p_config       jsonb,\n    p_descripcion  text    default null,\n    p_es_base      boolean default false,\n    p_reemplazar   boolean default false\n)\nreturns uuid\nlanguage plpgsql\nset search_path = public\nas $$\ndeclare\n    v_id        uuid;\n    v_cu        numeric := coalesce((p_config #>> \'{parametros_globales,costo_transporte_km_ton}\')::numeric, 1200);\n    v_pen_o     numeric := coalesce((p_config #>> \'{penalizaciones,factorPlanta}\')::numeric, 1000);\n    v_pen_c     numeric := coalesce((p_config #>> \'{penalizaciones,factorDemanda}\')::numeric, 1000);\n    v_desc      text    := coalesce(p_descripcion, p_config #>> \'{_meta,descripcion}\');\n    v_faltante  record;\nbegin\n    if p_nombre is null or length(trim(p_nombre)) = 0 then\n        raise exception \'El nombre del escenario es obligatorio\';\n    end if;\n    if jsonb_typeof(p_config -> \'agroempresas\') is distinct from \'array\'\n       or jsonb_array_length(p_config -> \'agroempresas\') = 0 then\n        raise exception \'El escenario debe tener al menos una agroempresa en "agroempresas"\';\n    end if;\n    if jsonb_typeof(p_config -> \'plantas\') is distinct from \'array\'\n       or jsonb_array_length(p_config -> \'plantas\') = 0 then\n        raise exception \'El escenario debe tener al menos una planta en "plantas"\';\n    end if;\n\n    -- los triggers de refresco se suspenden durante la carga y se refresca una vez al final\n    perform set_config(\'eco.sin_refresco\', \'on\', true);\n\n    select id into v_id from public.escenarios where nombre = p_nombre;\n\n    if v_id is not null and not p_reemplazar then\n        raise exception \'Ya existe el escenario "%". Use reemplazar = true para sobrescribirlo\', p_nombre\n            using errcode = \'23505\';\n    end if;\n\n    if p_es_base then\n        update public.escenarios set es_base = false\n        where es_base and id is distinct from v_id;\n    end if;\n\n    if v_id is null then\n        insert into public.escenarios (nombre, descripcion, es_base, costo_transporte_km_ton,\n                                       factor_penalizacion_oferta, factor_penalizacion_capacidad)\n        values (p_nombre, v_desc, p_es_base, v_cu, v_pen_o, v_pen_c)\n        returning id into v_id;\n    else\n        update public.escenarios\n        set descripcion                   = v_desc,\n            es_base                       = p_es_base or es_base,\n            costo_transporte_km_ton       = v_cu,\n            factor_penalizacion_oferta    = v_pen_o,\n            factor_penalizacion_capacidad = v_pen_c\n        where id = v_id;\n        delete from public.agroempresas where escenario_id = v_id;\n        delete from public.plantas      where escenario_id = v_id;\n    end if;\n\n    insert into public.plantas (escenario_id, codigo, nombre, municipio,\n                                capacidad_maxima_ton_sem, costo_operativo_ton, orden)\n    select v_id,\n           x ->> \'id\',\n           coalesce(x ->> \'nombre\', x ->> \'id\'),\n           x ->> \'municipio\',\n           (x ->> \'capacidad_maxima_ton_sem\')::numeric,\n           (x ->> \'costo_operativo_ton\')::numeric,\n           (ord - 1)::int\n    from jsonb_array_elements(p_config -> \'plantas\') with ordinality as t(x, ord);\n\n    insert into public.agroempresas (escenario_id, codigo, nombre, municipio, sector,\n                                     oferta_ton_sem, orden)\n    select v_id,\n           x ->> \'id\',\n           coalesce(x ->> \'nombre\', x ->> \'id\'),\n           x ->> \'municipio\',\n           x ->> \'sector\',\n           (x ->> \'oferta_ton_sem\')::numeric,\n           (ord - 1)::int\n    from jsonb_array_elements(p_config -> \'agroempresas\') with ordinality as t(x, ord);\n\n    select a.codigo as e, p.codigo as pl into v_faltante\n    from public.agroempresas a cross join public.plantas p\n    where a.escenario_id = v_id and p.escenario_id = v_id\n      and (p_config -> \'matriz_distancias_km\' -> a.codigo ->> p.codigo) is null\n    limit 1;\n    if found then\n        raise exception \'Falta la distancia de % a % en "matriz_distancias_km"\', v_faltante.e, v_faltante.pl;\n    end if;\n\n    insert into public.rutas (escenario_id, agroempresa_id, planta_id, distancia_km, habilitada)\n    select v_id, a.id, p.id,\n           (p_config -> \'matriz_distancias_km\' -> a.codigo ->> p.codigo)::numeric,\n           not coalesce(p_config -> \'rutas_deshabilitadas\' @> jsonb_build_array(jsonb_build_array(a.codigo, p.codigo)), false)\n    from public.agroempresas a cross join public.plantas p\n    where a.escenario_id = v_id and p.escenario_id = v_id;\n\n    perform set_config(\'eco.sin_refresco\', \'off\', true);\n    perform public.refrescar_parametros_entrada(v_id);\n    return v_id;\nend;\n$$;\n\n-- ---------------------------------------------------------------------\n-- clonar_escenario: copia completa; el original no se modifica (HU4)\n-- ---------------------------------------------------------------------\ncreate or replace function public.clonar_escenario(\n    p_origen       text,\n    p_nuevo        text,\n    p_variaciones  jsonb default \'{}\'::jsonb,\n    p_descripcion  text  default null\n)\nreturns uuid\nlanguage plpgsql\nset search_path = public\nas $$\ndeclare\n    v_cfg     jsonb := public.obtener_config_escenario(p_origen);\n    v_nuevo   uuid;\nbegin\n    v_nuevo := public.guardar_config_escenario(\n        p_nuevo, v_cfg, coalesce(p_descripcion, \'Copia de \' || p_origen), false, false);\n\n    update public.escenarios\n    set escenario_origen_id = (v_cfg #>> \'{_meta,escenario_id}\')::uuid,\n        variaciones         = coalesce(p_variaciones, \'{}\'::jsonb)\n    where id = v_nuevo;\n\n    return v_nuevo;\nend;\n$$;\n\n-- ---------------------------------------------------------------------\n-- Trigger de resultados (antes de insertar)\n--  1. Normaliza algoritmo_utilizado: \'exacto\' -> \'Exacto\', \'genetico\'/\'ag\' -> \'Genético\'\n--  2. Acepta matriz_flujos_json como lista de listas y le agrega los códigos\n--  3. Valida que la matriz tenga n × m (agroempresas × plantas) y sin negativos\n--  4. Calcula costo_transporte y costo_operativo si no vienen\n--  5. Calcula gap_desviacion contra el último resultado exacto del escenario\n-- ---------------------------------------------------------------------\ncreate or replace function public.tg_resultados_antes()\nreturns trigger\nlanguage plpgsql\nset search_path = public\nas $$\ndeclare\n    v_alg   text := lower(trim(new.algoritmo_utilizado));\n    v_mat   jsonb;\n    v_n     int;\n    v_m     int;\n    v_ex    public.resultados%rowtype;\nbegin\n    new.algoritmo_utilizado := case\n        when v_alg in (\'exacto\', \'exact\', \'pl\', \'lp\', \'simplex\') then \'Exacto\'\n        when v_alg in (\'genético\', \'genetico\', \'ag\', \'ga\', \'algoritmo genético\', \'algoritmo genetico\') then \'Genético\'\n        else new.algoritmo_utilizado end;\n\n    select count(*) into v_n from public.agroempresas where escenario_id = new.escenario_id;\n    select count(*) into v_m from public.plantas      where escenario_id = new.escenario_id;\n\n    if jsonb_typeof(new.matriz_flujos_json) = \'array\' then\n        new.matriz_flujos_json := jsonb_build_object(\'toneladas\', new.matriz_flujos_json);\n    end if;\n    v_mat := new.matriz_flujos_json -> \'toneladas\';\n\n    if jsonb_typeof(v_mat) is distinct from \'array\' or jsonb_array_length(v_mat) <> v_n\n       or exists (select 1 from jsonb_array_elements(v_mat) f\n                  where jsonb_typeof(f) <> \'array\' or jsonb_array_length(f) <> v_m) then\n        raise exception \'matriz_flujos_json debe ser una matriz de % filas (agroempresas) por % columnas (plantas)\', v_n, v_m\n            using errcode = \'22023\';\n    end if;\n    if exists (select 1 from jsonb_array_elements(v_mat) f, jsonb_array_elements(f) x\n               where jsonb_typeof(x) <> \'number\' or (x #>> \'{}\')::numeric < 0) then\n        raise exception \'matriz_flujos_json solo admite toneladas numéricas >= 0\' using errcode = \'22023\';\n    end if;\n\n    new.matriz_flujos_json := new.matriz_flujos_json\n        || jsonb_build_object(\n            \'agroempresas\', coalesce(new.matriz_flujos_json -> \'agroempresas\',\n                (select jsonb_agg(codigo order by orden) from public.agroempresas where escenario_id = new.escenario_id)),\n            \'plantas\', coalesce(new.matriz_flujos_json -> \'plantas\',\n                (select jsonb_agg(codigo order by orden) from public.plantas where escenario_id = new.escenario_id)));\n\n    if new.costo_transporte is null or new.costo_operativo is null then\n        select coalesce(new.costo_transporte, sum((x.val #>> \'{}\')::numeric * mc.costo_transporte_ton)),\n               coalesce(new.costo_operativo,  sum((x.val #>> \'{}\')::numeric * mc.costo_operativo_ton))\n          into new.costo_transporte, new.costo_operativo\n        from jsonb_array_elements(v_mat) with ordinality as f(fila, i)\n        cross join lateral jsonb_array_elements(f.fila) with ordinality as x(val, j)\n        join public.v_matriz_costos mc\n          on mc.escenario_id = new.escenario_id and mc.fila = f.i - 1 and mc.columna = x.j - 1;\n    end if;\n\n    if new.algoritmo_utilizado = \'Exacto\' then\n        new.gap_desviacion := 0;\n        new.resultado_exacto_id := null;\n    elsif new.gap_desviacion is null then\n        select * into v_ex from public.resultados\n        where escenario_id = new.escenario_id and algoritmo_utilizado = \'Exacto\'\n        order by fecha desc limit 1;\n        if v_ex.id is not null and v_ex.costo_total > 0 then\n            new.resultado_exacto_id := v_ex.id;\n            new.gap_desviacion := (new.costo_total - v_ex.costo_total) / v_ex.costo_total * 100;\n        end if;\n    end if;\n    return new;\nend;\n$$;\n\ndrop trigger if exists resultados_antes on public.resultados;\ncreate trigger resultados_antes before insert on public.resultados\n    for each row execute function public.tg_resultados_antes();\n\n-- Al guardar un resultado Exacto, completa el gap de los Genéticos que estaban sin referencia\ncreate or replace function public.tg_resultados_despues()\nreturns trigger\nlanguage plpgsql\nset search_path = public\nas $$\nbegin\n    if new.algoritmo_utilizado = \'Exacto\' and new.costo_total > 0 then\n        update public.resultados r\n        set gap_desviacion      = (r.costo_total - new.costo_total) / new.costo_total * 100,\n            resultado_exacto_id = new.id\n        where r.escenario_id = new.escenario_id\n          and r.algoritmo_utilizado = \'Genético\'\n          and r.gap_desviacion is null;\n    end if;\n    return null;\nend;\n$$;\n\ndrop trigger if exists resultados_despues on public.resultados;\ncreate trigger resultados_despues after insert on public.resultados\n    for each row execute function public.tg_resultados_despues();\n',
    'supabase/migrations/20261106000004_seguridad.sql': '-- =====================================================================\n-- PASO 4 · Seguridad\n--\n-- El backend (FastAPI + SQLAlchemy) se conecta directo a PostgreSQL con el\n-- usuario "postgres" del proyecto. Ese usuario es dueño de las tablas y no\n-- lo frena RLS. El navegador nunca se conecta a la base.\n--\n-- RLS activado y SIN políticas: la API pública de Supabase (claves anon /\n-- publishable) no puede leer ni escribir nada.\n-- =====================================================================\n\nalter table public.escenarios     enable row level security;\nalter table public.agroempresas   enable row level security;\nalter table public.plantas        enable row level security;\nalter table public.rutas          enable row level security;\nalter table public.resultados     enable row level security;\nalter table public.precios_sombra enable row level security;\n\ndo $$\ndeclare\n    f text;\nbegin\n    foreach f in array array[\n        \'public.refrescar_parametros_entrada(uuid)\',\n        \'public.obtener_config_escenario(text)\',\n        \'public.guardar_config_escenario(text, jsonb, text, boolean, boolean)\',\n        \'public.clonar_escenario(text, text, jsonb, text)\',\n        \'public.tg_refrescar_parametros()\',\n        \'public.tg_escenario_cu()\',\n        \'public.tg_resultados_antes()\',\n        \'public.tg_resultados_despues()\',\n        \'public.tg_actualizado_en()\'\n    ] loop\n        execute format(\'revoke execute on function %s from public\', f);\n        if exists (select 1 from pg_roles where rolname = \'anon\') then\n            execute format(\'revoke execute on function %s from anon, authenticated\', f);\n        end if;\n    end loop;\n\n    if exists (select 1 from pg_roles where rolname = \'anon\') then\n        revoke all on public.v_matriz_costos, public.v_resumen_escenarios,\n                      public.v_historial_comparativo from anon, authenticated;\n    end if;\nend;\n$$;\n',
    'supabase/crear_base_datos_ecoresiduos.sql': '-- =====================================================================\n-- EcoResiduos · Base de datos completa (pasos 1 a 4 en un solo archivo)\n-- Pegar TODO en Supabase > SQL Editor > New query > Run.\n-- Se puede volver a ejecutar sin perder datos.\n-- =====================================================================\n\n-- =====================================================================\n-- PASO 1 · Tablas\n-- EcoResiduos del Llano S.A.S. — Red logística de residuos agropecuarios\n--\n-- Tablas principales (las que pide el enunciado):\n--   * escenarios  : id, nombre, fecha y parametros_entrada (oferta, demanda, costos)\n--   * resultados  : id, escenario_id, algoritmo_utilizado (\'Exacto\' | \'Genético\'),\n--                   costo_total, tiempo_ejecucion_ms, gap_desviacion, matriz_flujos_json\n--\n-- Tablas de apoyo (detalle de la red y del análisis de sensibilidad):\n--   * agroempresas, plantas, rutas : la red G = (V, E) que se edita desde la web\n--   * precios_sombra               : duales uᵢ / vⱼ de cada resultado exacto\n--\n-- escenarios.parametros_entrada se calcula a partir de agroempresas, plantas\n-- y rutas (función refrescar_parametros_entrada, paso 3); nunca se edita a mano.\n-- =====================================================================\n\ncreate extension if not exists pgcrypto;  -- gen_random_uuid() (ya viene en Supabase)\n\n-- ---------------------------------------------------------------------\n-- escenarios\n-- ---------------------------------------------------------------------\ncreate table if not exists public.escenarios (\n    id                              uuid primary key default gen_random_uuid(),\n    nombre                          text not null unique\n                                    check (length(trim(nombre)) > 0),\n    fecha                           timestamptz not null default now(),\n    descripcion                     text,\n    -- {"fuentes": [...], "plantas": [...], "oferta": [...], "demanda": [...],\n    --  "costos": [[...]], "distancias_km": [[...]], "costo_transporte_km_ton": 1200, ...}\n    parametros_entrada              jsonb not null default \'{}\'::jsonb,\n    es_base                         boolean not null default false,\n    costo_transporte_km_ton         numeric not null default 1200\n                                    check (costo_transporte_km_ton >= 0),\n    factor_penalizacion_oferta      numeric not null default 1000\n                                    check (factor_penalizacion_oferta >= 0),\n    factor_penalizacion_capacidad   numeric not null default 1000\n                                    check (factor_penalizacion_capacidad >= 0),\n    escenario_origen_id             uuid references public.escenarios(id) on delete set null,\n    variaciones                     jsonb not null default \'{}\'::jsonb,\n    actualizado_en                  timestamptz not null default now()\n);\n\ncomment on column public.escenarios.fecha is \'Fecha de creación del escenario.\';\ncomment on column public.escenarios.parametros_entrada is\n    \'Parámetros de entrada del modelo: oferta, demanda (capacidad) y matriz de costos cᵢⱼ. Se calcula automáticamente.\';\ncomment on column public.escenarios.variaciones is\n    \'Variaciones aplicadas si el escenario es derivado, p. ej. {"variacion_costos_pct": 10}.\';\n\ncreate unique index if not exists escenarios_un_solo_base\n    on public.escenarios (es_base) where es_base;\n\n-- ---------------------------------------------------------------------\n-- agroempresas (fuentes, nodos de oferta)\n-- ---------------------------------------------------------------------\ncreate table if not exists public.agroempresas (\n    id              uuid primary key default gen_random_uuid(),\n    escenario_id    uuid not null references public.escenarios(id) on delete cascade,\n    codigo          text not null check (length(trim(codigo)) > 0),   -- \'E01\'\n    nombre          text not null check (length(trim(nombre)) > 0),\n    municipio       text,\n    sector          text,\n    oferta_ton_sem  numeric not null check (oferta_ton_sem >= 0),     -- Oᵢ\n    orden           integer not null check (orden >= 0),              -- fila i\n    unique (escenario_id, codigo),\n    unique (escenario_id, orden),\n    unique (id, escenario_id)\n);\n\n-- ---------------------------------------------------------------------\n-- plantas (destinos, nodos de demanda)\n-- ---------------------------------------------------------------------\ncreate table if not exists public.plantas (\n    id                          uuid primary key default gen_random_uuid(),\n    escenario_id                uuid not null references public.escenarios(id) on delete cascade,\n    codigo                      text not null check (length(trim(codigo)) > 0),  -- \'P1\'\n    nombre                      text not null check (length(trim(nombre)) > 0),\n    municipio                   text,\n    capacidad_maxima_ton_sem    numeric not null check (capacidad_maxima_ton_sem >= 0),  -- Dⱼ\n    costo_operativo_ton         numeric not null check (costo_operativo_ton >= 0),       -- cⱼᵒᵖ\n    orden                       integer not null check (orden >= 0),                     -- columna j\n    unique (escenario_id, codigo),\n    unique (escenario_id, orden),\n    unique (id, escenario_id)\n);\n\n-- ---------------------------------------------------------------------\n-- rutas (arcos (i,j) ∈ E)\n-- ---------------------------------------------------------------------\ncreate table if not exists public.rutas (\n    escenario_id    uuid not null references public.escenarios(id) on delete cascade,\n    agroempresa_id  uuid not null,\n    planta_id       uuid not null,\n    distancia_km    numeric not null check (distancia_km >= 0),   -- dᵢⱼ\n    habilitada      boolean not null default true,\n    primary key (agroempresa_id, planta_id),\n    foreign key (agroempresa_id, escenario_id)\n        references public.agroempresas (id, escenario_id) on delete cascade,\n    foreign key (planta_id, escenario_id)\n        references public.plantas (id, escenario_id) on delete cascade\n);\n\ncreate index if not exists rutas_escenario_idx on public.rutas (escenario_id);\n\n-- ---------------------------------------------------------------------\n-- resultados (una fila por cada ejecución del sistema)\n--\n-- matriz_flujos_json:\n--   {"agroempresas": ["E01", ...], "plantas": ["P1", ...],\n--    "toneladas": [[x11, x12, ...], ...]}          -- xᵢⱼ en t/semana\n--\n-- gap_desviacion (%) = (Z_AG − Z_exacto) / Z_exacto × 100\n--   * \'Exacto\'  -> 0\n--   * \'Genético\'-> se calcula solo contra el último resultado exacto del\n--                  mismo escenario (trigger del paso 3). Queda NULL si aún\n--                  no hay uno exacto y se completa cuando se guarde.\n-- ---------------------------------------------------------------------\ncreate table if not exists public.resultados (\n    id                      uuid primary key default gen_random_uuid(),\n    escenario_id            uuid not null references public.escenarios(id) on delete cascade,\n    algoritmo_utilizado     text not null check (algoritmo_utilizado in (\'Exacto\', \'Genético\')),\n    costo_total             numeric not null check (costo_total >= 0),        -- Z\n    tiempo_ejecucion_ms     double precision not null check (tiempo_ejecucion_ms >= 0),\n    gap_desviacion          numeric,                                         -- %\n    matriz_flujos_json      jsonb not null,\n    -- campos adicionales útiles para el informe\n    costo_transporte        numeric,\n    costo_operativo         numeric,\n    factible                boolean,\n    parametros_algoritmo    jsonb not null default \'{}\'::jsonb,   -- población, generaciones, solver...\n    historial_fitness       jsonb,                                -- convergencia del AG\n    resultado_exacto_id     uuid references public.resultados(id) on delete set null,  -- contra cuál se midió el gap\n    fecha                   timestamptz not null default now()\n);\n\ncomment on column public.resultados.gap_desviacion is\n    \'Gap (%) = (Z_AG − Z_exacto) / Z_exacto × 100, contra el último resultado exacto del escenario.\';\n\ncreate index if not exists resultados_escenario_idx\n    on public.resultados (escenario_id, algoritmo_utilizado, fecha desc);\n\n-- ---------------------------------------------------------------------\n-- precios_sombra (duales de un resultado exacto)\n-- ---------------------------------------------------------------------\ncreate table if not exists public.precios_sombra (\n    resultado_id    uuid not null references public.resultados(id) on delete cascade,\n    tipo            text not null check (tipo in (\'oferta\', \'capacidad\')),\n    nodo_codigo     text not null,\n    valor_dual      numeric not null,\n    holgura         numeric,\n    rango_inferior  numeric,\n    rango_superior  numeric,\n    primary key (resultado_id, tipo, nodo_codigo)\n);\n\n-- ---------------------------------------------------------------------\n-- actualizado_en automático\n-- ---------------------------------------------------------------------\ncreate or replace function public.tg_actualizado_en()\nreturns trigger language plpgsql\nset search_path = public\nas $$\nbegin\n    new.actualizado_en := now();\n    return new;\nend;\n$$;\n\ndrop trigger if exists escenarios_actualizado_en on public.escenarios;\ncreate trigger escenarios_actualizado_en\n    before update on public.escenarios\n    for each row execute function public.tg_actualizado_en();\n\n-- =====================================================================\n-- PASO 2 · Vistas de consulta\n-- =====================================================================\n\n-- ---------------------------------------------------------------------\n-- Matriz de costos unitarios: cᵢⱼ = cᵤ·dᵢⱼ + cⱼᵒᵖ   [COP/ton]\n-- ---------------------------------------------------------------------\ncreate or replace view public.v_matriz_costos\nwith (security_invoker = true) as\nselect\n    r.escenario_id,\n    a.codigo                                    as agroempresa_codigo,\n    p.codigo                                    as planta_codigo,\n    a.orden                                     as fila,\n    p.orden                                     as columna,\n    r.distancia_km,\n    e.costo_transporte_km_ton,\n    p.costo_operativo_ton,\n    e.costo_transporte_km_ton * r.distancia_km  as costo_transporte_ton,\n    e.costo_transporte_km_ton * r.distancia_km\n        + p.costo_operativo_ton                 as costo_unitario,\n    r.habilitada\nfrom public.rutas r\njoin public.escenarios   e on e.id = r.escenario_id\njoin public.agroempresas a on a.id = r.agroempresa_id\njoin public.plantas      p on p.id = r.planta_id;\n\n-- ---------------------------------------------------------------------\n-- Historial de escenarios con tamaño de la red, balance y nº de resultados\n-- ---------------------------------------------------------------------\ncreate or replace view public.v_resumen_escenarios\nwith (security_invoker = true) as\nselect\n    e.id,\n    e.nombre,\n    e.fecha,\n    e.descripcion,\n    e.es_base,\n    e.costo_transporte_km_ton,\n    coalesce(a.n, 0)                               as num_agroempresas,\n    coalesce(p.n, 0)                               as num_plantas,\n    coalesce(r.n, 0)                               as num_rutas_habilitadas,\n    coalesce(a.total, 0)                           as oferta_total,\n    coalesce(p.total, 0)                           as capacidad_total,\n    coalesce(p.total, 0) - coalesce(a.total, 0)    as holgura_capacidad,\n    case\n        when coalesce(a.total, 0) = coalesce(p.total, 0) then \'balanceada\'\n        when coalesce(a.total, 0) < coalesce(p.total, 0) then \'capacidad_sobrante\'\n        else \'oferta_excedente\'\n    end                                            as estado_balance,\n    coalesce(res.n, 0)                             as num_resultados,\n    res.ultima                                     as fecha_ultimo_resultado,\n    e.escenario_origen_id,\n    e.variaciones,\n    e.actualizado_en\nfrom public.escenarios e\nleft join (select escenario_id, count(*) n, sum(oferta_ton_sem) total\n           from public.agroempresas group by escenario_id) a on a.escenario_id = e.id\nleft join (select escenario_id, count(*) n, sum(capacidad_maxima_ton_sem) total\n           from public.plantas group by escenario_id) p on p.escenario_id = e.id\nleft join (select escenario_id, count(*) n\n           from public.rutas where habilitada group by escenario_id) r on r.escenario_id = e.id\nleft join (select escenario_id, count(*) n, max(fecha) ultima\n           from public.resultados group by escenario_id) res on res.escenario_id = e.id;\n\n-- ---------------------------------------------------------------------\n-- Análisis comparativo: último Exacto vs. último Genético de cada escenario\n-- ---------------------------------------------------------------------\ncreate or replace view public.v_historial_comparativo\nwith (security_invoker = true) as\nwith ultimo as (\n    select distinct on (escenario_id, algoritmo_utilizado) *\n    from public.resultados\n    order by escenario_id, algoritmo_utilizado, fecha desc\n)\nselect\n    e.id                        as escenario_id,\n    e.nombre                    as escenario,\n    e.fecha                     as fecha_escenario,\n    ex.id                       as resultado_exacto_id,\n    ag.id                       as resultado_genetico_id,\n    ex.costo_total              as costo_exacto,\n    ag.costo_total              as costo_genetico,\n    case when ex.costo_total > 0\n         then (ag.costo_total - ex.costo_total) / ex.costo_total * 100\n    end                         as gap_desviacion,\n    ex.tiempo_ejecucion_ms      as tiempo_exacto_ms,\n    ag.tiempo_ejecucion_ms      as tiempo_genetico_ms,\n    ag.factible                 as genetico_factible,\n    ag.parametros_algoritmo     as parametros_ag,\n    greatest(ex.fecha, ag.fecha) as fecha_ultimo_resultado\nfrom public.escenarios e\nleft join ultimo ex on ex.escenario_id = e.id and ex.algoritmo_utilizado = \'Exacto\'\nleft join ultimo ag on ag.escenario_id = e.id and ag.algoritmo_utilizado = \'Genético\'\nwhere ex.id is not null or ag.id is not null;\n\n-- =====================================================================\n-- PASO 3 · Funciones y triggers\n--\n--   refrescar_parametros_entrada(id)  -> recalcula escenarios.parametros_entrada\n--   obtener_config_escenario(nombre)  -> jsonb con el MISMO formato de dataConfig.json\n--   guardar_config_escenario(...)     -> crea/reemplaza un escenario desde ese formato\n--   clonar_escenario(...)             -> copia para sensibilidad (HU4) o HU8\n--   trigger de resultados             -> normaliza el algoritmo, valida la matriz,\n--                                        desglosa el costo y calcula el gap\n-- =====================================================================\n\n-- ---------------------------------------------------------------------\n-- refrescar_parametros_entrada\n-- Construye: fuentes, plantas, oferta, demanda, costo_operativo,\n-- distancias_km, costos (cᵢⱼ), costo_transporte_km_ton, totales.\n-- ---------------------------------------------------------------------\ncreate or replace function public.refrescar_parametros_entrada(p_escenario uuid)\nreturns void\nlanguage plpgsql\nset search_path = public\nas $$\nbegin\n    update public.escenarios e\n    set parametros_entrada = jsonb_build_object(\n        \'fuentes\',  coalesce((select jsonb_agg(a.codigo order by a.orden)\n                              from public.agroempresas a where a.escenario_id = e.id), \'[]\'::jsonb),\n        \'plantas\',  coalesce((select jsonb_agg(p.codigo order by p.orden)\n                              from public.plantas p where p.escenario_id = e.id), \'[]\'::jsonb),\n        \'oferta\',   coalesce((select jsonb_agg(a.oferta_ton_sem order by a.orden)\n                              from public.agroempresas a where a.escenario_id = e.id), \'[]\'::jsonb),\n        \'demanda\',  coalesce((select jsonb_agg(p.capacidad_maxima_ton_sem order by p.orden)\n                              from public.plantas p where p.escenario_id = e.id), \'[]\'::jsonb),\n        \'costo_operativo\', coalesce((select jsonb_agg(p.costo_operativo_ton order by p.orden)\n                              from public.plantas p where p.escenario_id = e.id), \'[]\'::jsonb),\n        \'costo_transporte_km_ton\', e.costo_transporte_km_ton,\n        \'distancias_km\', coalesce((\n            select jsonb_agg(f.fila order by f.fila_i) from (\n                select mc.fila as fila_i, jsonb_agg(mc.distancia_km order by mc.columna) as fila\n                from public.v_matriz_costos mc where mc.escenario_id = e.id\n                group by mc.fila) f), \'[]\'::jsonb),\n        \'costos\', coalesce((\n            select jsonb_agg(f.fila order by f.fila_i) from (\n                select mc.fila as fila_i, jsonb_agg(mc.costo_unitario order by mc.columna) as fila\n                from public.v_matriz_costos mc where mc.escenario_id = e.id\n                group by mc.fila) f), \'[]\'::jsonb),\n        \'rutas_deshabilitadas\', coalesce((\n            select jsonb_agg(jsonb_build_array(mc.agroempresa_codigo, mc.planta_codigo)\n                             order by mc.fila, mc.columna)\n            from public.v_matriz_costos mc where mc.escenario_id = e.id and not mc.habilitada), \'[]\'::jsonb),\n        \'oferta_total\',    coalesce((select sum(a.oferta_ton_sem)\n                                     from public.agroempresas a where a.escenario_id = e.id), 0),\n        \'capacidad_total\', coalesce((select sum(p.capacidad_maxima_ton_sem)\n                                     from public.plantas p where p.escenario_id = e.id), 0),\n        \'unidades\', jsonb_build_object(\'oferta_demanda\', \'t/semana\', \'costos\', \'COP/t\',\n                                       \'distancias\', \'km\', \'costo_transporte\', \'COP/(km·t)\')\n    )\n    where e.id = p_escenario;\nend;\n$$;\n\n-- Mantener parametros_entrada al día si se edita la red desde el ORM o el Table Editor\ncreate or replace function public.tg_refrescar_parametros()\nreturns trigger\nlanguage plpgsql\nset search_path = public\nas $$\nbegin\n    if coalesce(current_setting(\'eco.sin_refresco\', true), \'\') = \'on\' then\n        return null;\n    end if;\n    if tg_op in (\'INSERT\', \'UPDATE\') then\n        perform public.refrescar_parametros_entrada(new.escenario_id);\n    end if;\n    if tg_op in (\'UPDATE\', \'DELETE\') and (tg_op = \'DELETE\' or old.escenario_id <> new.escenario_id) then\n        perform public.refrescar_parametros_entrada(old.escenario_id);\n    end if;\n    return null;\nend;\n$$;\n\ndrop trigger if exists agroempresas_refrescar on public.agroempresas;\ncreate trigger agroempresas_refrescar after insert or update or delete on public.agroempresas\n    for each row execute function public.tg_refrescar_parametros();\ndrop trigger if exists plantas_refrescar on public.plantas;\ncreate trigger plantas_refrescar after insert or update or delete on public.plantas\n    for each row execute function public.tg_refrescar_parametros();\ndrop trigger if exists rutas_refrescar on public.rutas;\ncreate trigger rutas_refrescar after insert or update or delete on public.rutas\n    for each row execute function public.tg_refrescar_parametros();\n\ncreate or replace function public.tg_escenario_cu()\nreturns trigger\nlanguage plpgsql\nset search_path = public\nas $$\nbegin\n    perform public.refrescar_parametros_entrada(new.id);\n    return null;\nend;\n$$;\n\ndrop trigger if exists escenarios_refrescar_cu on public.escenarios;\ncreate trigger escenarios_refrescar_cu after update of costo_transporte_km_ton on public.escenarios\n    for each row execute function public.tg_escenario_cu();\n\n-- ---------------------------------------------------------------------\n-- obtener_config_escenario: mismas claves que dataConfig.json\n-- (EvaluadorFitness lee la penalización de oferta en "factorPlanta"\n--  y la de capacidad en "factorDemanda")\n-- ---------------------------------------------------------------------\ncreate or replace function public.obtener_config_escenario(p_nombre text)\nreturns jsonb\nlanguage plpgsql stable\nset search_path = public\nas $$\ndeclare\n    e   public.escenarios%rowtype;\nbegin\n    select * into e from public.escenarios where nombre = p_nombre;\n    if not found then\n        raise exception \'No existe el escenario "%"\', p_nombre using errcode = \'P0002\';\n    end if;\n\n    return jsonb_build_object(\n        \'_meta\', jsonb_build_object(\n            \'escenario_id\',        e.id,\n            \'nombre\',              e.nombre,\n            \'fecha\',               e.fecha,\n            \'descripcion\',         e.descripcion,\n            \'es_base\',             e.es_base,\n            \'escenario_origen_id\', e.escenario_origen_id,\n            \'variaciones\',         e.variaciones,\n            \'fuente\',              \'base_de_datos\'\n        ),\n        \'parametros_globales\', jsonb_build_object(\n            \'costo_transporte_km_ton\', e.costo_transporte_km_ton\n        ),\n        \'penalizaciones\', jsonb_build_object(\n            \'factorPlanta\',  e.factor_penalizacion_oferta,\n            \'factorDemanda\', e.factor_penalizacion_capacidad\n        ),\n        \'plantas\', (\n            select coalesce(jsonb_agg(jsonb_build_object(\n                       \'id\',                       p.codigo,\n                       \'nombre\',                   p.nombre,\n                       \'municipio\',                p.municipio,\n                       \'capacidad_maxima_ton_sem\', p.capacidad_maxima_ton_sem,\n                       \'costo_operativo_ton\',      p.costo_operativo_ton\n                   ) order by p.orden), \'[]\'::jsonb)\n            from public.plantas p where p.escenario_id = e.id\n        ),\n        \'agroempresas\', (\n            select coalesce(jsonb_agg(jsonb_build_object(\n                       \'id\',             a.codigo,\n                       \'nombre\',         a.nombre,\n                       \'municipio\',      a.municipio,\n                       \'sector\',         a.sector,\n                       \'oferta_ton_sem\', a.oferta_ton_sem\n                   ) order by a.orden), \'[]\'::jsonb)\n            from public.agroempresas a where a.escenario_id = e.id\n        ),\n        \'matriz_distancias_km\', (\n            select coalesce(jsonb_object_agg(f.codigo, f.fila), \'{}\'::jsonb)\n            from (\n                select a.codigo, jsonb_object_agg(p.codigo, r.distancia_km) as fila\n                from public.rutas r\n                join public.agroempresas a on a.id = r.agroempresa_id\n                join public.plantas      p on p.id = r.planta_id\n                where r.escenario_id = e.id\n                group by a.codigo\n            ) f\n        ),\n        \'rutas_deshabilitadas\', e.parametros_entrada -> \'rutas_deshabilitadas\'\n    );\nend;\n$$;\n\n-- ---------------------------------------------------------------------\n-- guardar_config_escenario\n-- Recibe el formato de dataConfig.json. Exige distancia para cada pareja\n-- agroempresa-planta; una ruta se retira con\n--   "rutas_deshabilitadas": [["E01","P4"], ...].\n-- Con p_reemplazar = true sobrescribe la red (los resultados se conservan).\n-- ---------------------------------------------------------------------\ncreate or replace function public.guardar_config_escenario(\n    p_nombre       text,\n    p_config       jsonb,\n    p_descripcion  text    default null,\n    p_es_base      boolean default false,\n    p_reemplazar   boolean default false\n)\nreturns uuid\nlanguage plpgsql\nset search_path = public\nas $$\ndeclare\n    v_id        uuid;\n    v_cu        numeric := coalesce((p_config #>> \'{parametros_globales,costo_transporte_km_ton}\')::numeric, 1200);\n    v_pen_o     numeric := coalesce((p_config #>> \'{penalizaciones,factorPlanta}\')::numeric, 1000);\n    v_pen_c     numeric := coalesce((p_config #>> \'{penalizaciones,factorDemanda}\')::numeric, 1000);\n    v_desc      text    := coalesce(p_descripcion, p_config #>> \'{_meta,descripcion}\');\n    v_faltante  record;\nbegin\n    if p_nombre is null or length(trim(p_nombre)) = 0 then\n        raise exception \'El nombre del escenario es obligatorio\';\n    end if;\n    if jsonb_typeof(p_config -> \'agroempresas\') is distinct from \'array\'\n       or jsonb_array_length(p_config -> \'agroempresas\') = 0 then\n        raise exception \'El escenario debe tener al menos una agroempresa en "agroempresas"\';\n    end if;\n    if jsonb_typeof(p_config -> \'plantas\') is distinct from \'array\'\n       or jsonb_array_length(p_config -> \'plantas\') = 0 then\n        raise exception \'El escenario debe tener al menos una planta en "plantas"\';\n    end if;\n\n    -- los triggers de refresco se suspenden durante la carga y se refresca una vez al final\n    perform set_config(\'eco.sin_refresco\', \'on\', true);\n\n    select id into v_id from public.escenarios where nombre = p_nombre;\n\n    if v_id is not null and not p_reemplazar then\n        raise exception \'Ya existe el escenario "%". Use reemplazar = true para sobrescribirlo\', p_nombre\n            using errcode = \'23505\';\n    end if;\n\n    if p_es_base then\n        update public.escenarios set es_base = false\n        where es_base and id is distinct from v_id;\n    end if;\n\n    if v_id is null then\n        insert into public.escenarios (nombre, descripcion, es_base, costo_transporte_km_ton,\n                                       factor_penalizacion_oferta, factor_penalizacion_capacidad)\n        values (p_nombre, v_desc, p_es_base, v_cu, v_pen_o, v_pen_c)\n        returning id into v_id;\n    else\n        update public.escenarios\n        set descripcion                   = v_desc,\n            es_base                       = p_es_base or es_base,\n            costo_transporte_km_ton       = v_cu,\n            factor_penalizacion_oferta    = v_pen_o,\n            factor_penalizacion_capacidad = v_pen_c\n        where id = v_id;\n        delete from public.agroempresas where escenario_id = v_id;\n        delete from public.plantas      where escenario_id = v_id;\n    end if;\n\n    insert into public.plantas (escenario_id, codigo, nombre, municipio,\n                                capacidad_maxima_ton_sem, costo_operativo_ton, orden)\n    select v_id,\n           x ->> \'id\',\n           coalesce(x ->> \'nombre\', x ->> \'id\'),\n           x ->> \'municipio\',\n           (x ->> \'capacidad_maxima_ton_sem\')::numeric,\n           (x ->> \'costo_operativo_ton\')::numeric,\n           (ord - 1)::int\n    from jsonb_array_elements(p_config -> \'plantas\') with ordinality as t(x, ord);\n\n    insert into public.agroempresas (escenario_id, codigo, nombre, municipio, sector,\n                                     oferta_ton_sem, orden)\n    select v_id,\n           x ->> \'id\',\n           coalesce(x ->> \'nombre\', x ->> \'id\'),\n           x ->> \'municipio\',\n           x ->> \'sector\',\n           (x ->> \'oferta_ton_sem\')::numeric,\n           (ord - 1)::int\n    from jsonb_array_elements(p_config -> \'agroempresas\') with ordinality as t(x, ord);\n\n    select a.codigo as e, p.codigo as pl into v_faltante\n    from public.agroempresas a cross join public.plantas p\n    where a.escenario_id = v_id and p.escenario_id = v_id\n      and (p_config -> \'matriz_distancias_km\' -> a.codigo ->> p.codigo) is null\n    limit 1;\n    if found then\n        raise exception \'Falta la distancia de % a % en "matriz_distancias_km"\', v_faltante.e, v_faltante.pl;\n    end if;\n\n    insert into public.rutas (escenario_id, agroempresa_id, planta_id, distancia_km, habilitada)\n    select v_id, a.id, p.id,\n           (p_config -> \'matriz_distancias_km\' -> a.codigo ->> p.codigo)::numeric,\n           not coalesce(p_config -> \'rutas_deshabilitadas\' @> jsonb_build_array(jsonb_build_array(a.codigo, p.codigo)), false)\n    from public.agroempresas a cross join public.plantas p\n    where a.escenario_id = v_id and p.escenario_id = v_id;\n\n    perform set_config(\'eco.sin_refresco\', \'off\', true);\n    perform public.refrescar_parametros_entrada(v_id);\n    return v_id;\nend;\n$$;\n\n-- ---------------------------------------------------------------------\n-- clonar_escenario: copia completa; el original no se modifica (HU4)\n-- ---------------------------------------------------------------------\ncreate or replace function public.clonar_escenario(\n    p_origen       text,\n    p_nuevo        text,\n    p_variaciones  jsonb default \'{}\'::jsonb,\n    p_descripcion  text  default null\n)\nreturns uuid\nlanguage plpgsql\nset search_path = public\nas $$\ndeclare\n    v_cfg     jsonb := public.obtener_config_escenario(p_origen);\n    v_nuevo   uuid;\nbegin\n    v_nuevo := public.guardar_config_escenario(\n        p_nuevo, v_cfg, coalesce(p_descripcion, \'Copia de \' || p_origen), false, false);\n\n    update public.escenarios\n    set escenario_origen_id = (v_cfg #>> \'{_meta,escenario_id}\')::uuid,\n        variaciones         = coalesce(p_variaciones, \'{}\'::jsonb)\n    where id = v_nuevo;\n\n    return v_nuevo;\nend;\n$$;\n\n-- ---------------------------------------------------------------------\n-- Trigger de resultados (antes de insertar)\n--  1. Normaliza algoritmo_utilizado: \'exacto\' -> \'Exacto\', \'genetico\'/\'ag\' -> \'Genético\'\n--  2. Acepta matriz_flujos_json como lista de listas y le agrega los códigos\n--  3. Valida que la matriz tenga n × m (agroempresas × plantas) y sin negativos\n--  4. Calcula costo_transporte y costo_operativo si no vienen\n--  5. Calcula gap_desviacion contra el último resultado exacto del escenario\n-- ---------------------------------------------------------------------\ncreate or replace function public.tg_resultados_antes()\nreturns trigger\nlanguage plpgsql\nset search_path = public\nas $$\ndeclare\n    v_alg   text := lower(trim(new.algoritmo_utilizado));\n    v_mat   jsonb;\n    v_n     int;\n    v_m     int;\n    v_ex    public.resultados%rowtype;\nbegin\n    new.algoritmo_utilizado := case\n        when v_alg in (\'exacto\', \'exact\', \'pl\', \'lp\', \'simplex\') then \'Exacto\'\n        when v_alg in (\'genético\', \'genetico\', \'ag\', \'ga\', \'algoritmo genético\', \'algoritmo genetico\') then \'Genético\'\n        else new.algoritmo_utilizado end;\n\n    select count(*) into v_n from public.agroempresas where escenario_id = new.escenario_id;\n    select count(*) into v_m from public.plantas      where escenario_id = new.escenario_id;\n\n    if jsonb_typeof(new.matriz_flujos_json) = \'array\' then\n        new.matriz_flujos_json := jsonb_build_object(\'toneladas\', new.matriz_flujos_json);\n    end if;\n    v_mat := new.matriz_flujos_json -> \'toneladas\';\n\n    if jsonb_typeof(v_mat) is distinct from \'array\' or jsonb_array_length(v_mat) <> v_n\n       or exists (select 1 from jsonb_array_elements(v_mat) f\n                  where jsonb_typeof(f) <> \'array\' or jsonb_array_length(f) <> v_m) then\n        raise exception \'matriz_flujos_json debe ser una matriz de % filas (agroempresas) por % columnas (plantas)\', v_n, v_m\n            using errcode = \'22023\';\n    end if;\n    if exists (select 1 from jsonb_array_elements(v_mat) f, jsonb_array_elements(f) x\n               where jsonb_typeof(x) <> \'number\' or (x #>> \'{}\')::numeric < 0) then\n        raise exception \'matriz_flujos_json solo admite toneladas numéricas >= 0\' using errcode = \'22023\';\n    end if;\n\n    new.matriz_flujos_json := new.matriz_flujos_json\n        || jsonb_build_object(\n            \'agroempresas\', coalesce(new.matriz_flujos_json -> \'agroempresas\',\n                (select jsonb_agg(codigo order by orden) from public.agroempresas where escenario_id = new.escenario_id)),\n            \'plantas\', coalesce(new.matriz_flujos_json -> \'plantas\',\n                (select jsonb_agg(codigo order by orden) from public.plantas where escenario_id = new.escenario_id)));\n\n    if new.costo_transporte is null or new.costo_operativo is null then\n        select coalesce(new.costo_transporte, sum((x.val #>> \'{}\')::numeric * mc.costo_transporte_ton)),\n               coalesce(new.costo_operativo,  sum((x.val #>> \'{}\')::numeric * mc.costo_operativo_ton))\n          into new.costo_transporte, new.costo_operativo\n        from jsonb_array_elements(v_mat) with ordinality as f(fila, i)\n        cross join lateral jsonb_array_elements(f.fila) with ordinality as x(val, j)\n        join public.v_matriz_costos mc\n          on mc.escenario_id = new.escenario_id and mc.fila = f.i - 1 and mc.columna = x.j - 1;\n    end if;\n\n    if new.algoritmo_utilizado = \'Exacto\' then\n        new.gap_desviacion := 0;\n        new.resultado_exacto_id := null;\n    elsif new.gap_desviacion is null then\n        select * into v_ex from public.resultados\n        where escenario_id = new.escenario_id and algoritmo_utilizado = \'Exacto\'\n        order by fecha desc limit 1;\n        if v_ex.id is not null and v_ex.costo_total > 0 then\n            new.resultado_exacto_id := v_ex.id;\n            new.gap_desviacion := (new.costo_total - v_ex.costo_total) / v_ex.costo_total * 100;\n        end if;\n    end if;\n    return new;\nend;\n$$;\n\ndrop trigger if exists resultados_antes on public.resultados;\ncreate trigger resultados_antes before insert on public.resultados\n    for each row execute function public.tg_resultados_antes();\n\n-- Al guardar un resultado Exacto, completa el gap de los Genéticos que estaban sin referencia\ncreate or replace function public.tg_resultados_despues()\nreturns trigger\nlanguage plpgsql\nset search_path = public\nas $$\nbegin\n    if new.algoritmo_utilizado = \'Exacto\' and new.costo_total > 0 then\n        update public.resultados r\n        set gap_desviacion      = (r.costo_total - new.costo_total) / new.costo_total * 100,\n            resultado_exacto_id = new.id\n        where r.escenario_id = new.escenario_id\n          and r.algoritmo_utilizado = \'Genético\'\n          and r.gap_desviacion is null;\n    end if;\n    return null;\nend;\n$$;\n\ndrop trigger if exists resultados_despues on public.resultados;\ncreate trigger resultados_despues after insert on public.resultados\n    for each row execute function public.tg_resultados_despues();\n\n-- =====================================================================\n-- PASO 4 · Seguridad\n--\n-- El backend (FastAPI + SQLAlchemy) se conecta directo a PostgreSQL con el\n-- usuario "postgres" del proyecto. Ese usuario es dueño de las tablas y no\n-- lo frena RLS. El navegador nunca se conecta a la base.\n--\n-- RLS activado y SIN políticas: la API pública de Supabase (claves anon /\n-- publishable) no puede leer ni escribir nada.\n-- =====================================================================\n\nalter table public.escenarios     enable row level security;\nalter table public.agroempresas   enable row level security;\nalter table public.plantas        enable row level security;\nalter table public.rutas          enable row level security;\nalter table public.resultados     enable row level security;\nalter table public.precios_sombra enable row level security;\n\ndo $$\ndeclare\n    f text;\nbegin\n    foreach f in array array[\n        \'public.refrescar_parametros_entrada(uuid)\',\n        \'public.obtener_config_escenario(text)\',\n        \'public.guardar_config_escenario(text, jsonb, text, boolean, boolean)\',\n        \'public.clonar_escenario(text, text, jsonb, text)\',\n        \'public.tg_refrescar_parametros()\',\n        \'public.tg_escenario_cu()\',\n        \'public.tg_resultados_antes()\',\n        \'public.tg_resultados_despues()\',\n        \'public.tg_actualizado_en()\'\n    ] loop\n        execute format(\'revoke execute on function %s from public\', f);\n        if exists (select 1 from pg_roles where rolname = \'anon\') then\n            execute format(\'revoke execute on function %s from anon, authenticated\', f);\n        end if;\n    end loop;\n\n    if exists (select 1 from pg_roles where rolname = \'anon\') then\n        revoke all on public.v_matriz_costos, public.v_resumen_escenarios,\n                      public.v_historial_comparativo from anon, authenticated;\n    end if;\nend;\n$$;\n\n',
    'supabase/reiniciar_base_datos.sql': '-- =====================================================================\n-- REINICIAR LA BASE DE DATOS (ejecutar UNA sola vez)\n--\n-- Borra las tablas, vistas y funciones de la versión anterior\n-- (ejecuciones, asignaciones, comparativos...) y TODOS sus datos.\n-- Después se ejecuta crear_base_datos_ecoresiduos.sql y se vuelve a\n-- cargar el caso base con:  python -m scripts.sembrar_bd\n--\n-- ⚠ No lo ejecuten cuando ya tengan resultados que quieran conservar.\n-- =====================================================================\n\ndrop view if exists public.v_comparativos, public.v_historial_comparativo,\n                    public.v_resumen_escenarios, public.v_matriz_costos cascade;\n\ndrop table if exists public.comparativos, public.precios_sombra, public.asignaciones,\n                     public.ejecuciones, public.resultados, public.rutas,\n                     public.agroempresas, public.plantas, public.escenarios cascade;\n\ndrop function if exists public.guardar_ejecucion(text, jsonb) cascade;\ndrop function if exists public.registrar_comparativo(uuid, uuid, text) cascade;\ndrop function if exists public.clonar_escenario(text, text, jsonb, text) cascade;\ndrop function if exists public.guardar_config_escenario(text, jsonb, text, boolean, boolean) cascade;\ndrop function if exists public.obtener_config_escenario(text) cascade;\ndrop function if exists public.refrescar_parametros_entrada(uuid) cascade;\ndrop function if exists public.tg_refrescar_parametros() cascade;\ndrop function if exists public.tg_escenario_cu() cascade;\ndrop function if exists public.tg_resultados_antes() cascade;\ndrop function if exists public.tg_resultados_despues() cascade;\ndrop function if exists public.tg_actualizado_en() cascade;\n',
    'backend/app/core/config.py': '"""Configuración global leída desde variables de entorno (.env)."""\nfrom pydantic_settings import BaseSettings, SettingsConfigDict\n\n\nclass Settings(BaseSettings):\n    app_nombre: str = "EcoResiduos API"\n    cors_origenes: str = "http://localhost:5173"\n\n    # Base de datos\n    #   FUENTE_DATOS=json -> lee backend/data/escenarios/*.json (sin base de datos)\n    #   FUENTE_DATOS=bd   -> PostgreSQL (Supabase) con SQLAlchemy\n    fuente_datos: str = "json"\n    database_url: str = ""        # cadena de conexión de Supabase (Session pooler)\n    database_password: str = ""   # opcional: contraseña aparte, sin tener que codificarla en la URL\n\n    # ignora variables que sobren en el .env (p. ej. las de versiones anteriores)\n    model_config = SettingsConfigDict(env_file=".env", extra="ignore")\n\n    @property\n    def usa_bd(self) -> bool:\n        return self.fuente_datos.strip().lower() in {"bd", "supabase", "postgres", "postgresql"}\n\n    @property\n    def cors_origenes_lista(self) -> list[str]:\n        return [o.strip() for o in self.cors_origenes.split(",")]\n\n\nsettings = Settings()\n',
    'backend/app/db/__init__.py': '"""Acceso a la base de datos PostgreSQL (Supabase) con SQLAlchemy."""\n',
    'backend/app/db/sesion.py': '"""Conexión a PostgreSQL: motor de SQLAlchemy, sesiones y manejo de errores."""\nfrom contextlib import contextmanager\nfrom functools import lru_cache\nfrom typing import Iterator\n\nfrom sqlalchemy import create_engine\nfrom sqlalchemy.engine import Engine, make_url\nfrom sqlalchemy.exc import DBAPIError, OperationalError\nfrom sqlalchemy.orm import Session, sessionmaker\n\nfrom app.core.config import settings\n\n\nclass ErrorBaseDatos(RuntimeError):\n    """Error de la base de datos con un mensaje legible y el código HTTP sugerido."""\n\n    def __init__(self, mensaje: str, codigo_http: int = 400, codigo_pg: str | None = None):\n        super().__init__(mensaje)\n        self.mensaje = mensaje\n        self.codigo_http = codigo_http\n        self.codigo_pg = codigo_pg\n\n\nclass BDNoConfigurada(ErrorBaseDatos):\n    def __init__(self, mensaje: str):\n        super().__init__(mensaje, 503)\n\n\nclass EscenarioNoEncontrado(ErrorBaseDatos):\n    def __init__(self, mensaje: str):\n        super().__init__(mensaje, 404, "P0002")\n\n\n# códigos de PostgreSQL -> código HTTP\n_HTTP_POR_PG = {\n    "P0002": 404,   # no existe (lanzado por las funciones SQL)\n    "23505": 409,   # nombre duplicado\n    "23514": 422,   # viola un CHECK (p. ej. oferta negativa)\n    "23502": 422,   # falta un campo obligatorio\n    "22023": 422,   # dato inválido (p. ej. matriz de tamaño incorrecto)\n    "22P02": 422,   # formato inválido\n    "P0001": 422,   # raise exception de las funciones\n}\n\n\ndef traducir_error(e: Exception) -> ErrorBaseDatos:\n    if isinstance(e, ErrorBaseDatos):\n        return e\n    if isinstance(e, OperationalError):\n        return ErrorBaseDatos(f"No se pudo conectar a la base de datos: {e.orig}", 503)\n    if isinstance(e, DBAPIError) and e.orig is not None:\n        codigo = getattr(e.orig, "pgcode", None)\n        diag = getattr(e.orig, "diag", None)\n        mensaje = (getattr(diag, "message_primary", None) or str(e.orig)).strip()\n        if codigo == "P0002":\n            return EscenarioNoEncontrado(mensaje)\n        return ErrorBaseDatos(mensaje, _HTTP_POR_PG.get(codigo, 400), codigo)\n    return ErrorBaseDatos(str(e), 500)\n\n\ndef _url_conexion():\n    if not settings.database_url:\n        raise BDNoConfigurada("Falta DATABASE_URL en backend/.env (o FUENTE_DATOS no es \'bd\')")\n    url = settings.database_url.strip()\n    if settings.database_password:\n        # quita el marcador de Supabase y deja que SQLAlchemy codifique la contraseña\n        url = url.replace(":[YOUR-PASSWORD]@", "@")\n        url_obj = make_url(url).set(password=settings.database_password)\n    else:\n        url_obj = make_url(url)\n    if url_obj.drivername in ("postgres", "postgresql"):\n        url_obj = url_obj.set(drivername="postgresql+psycopg2")\n    if url_obj.host and url_obj.host.endswith("supabase.com") and "sslmode" not in url_obj.query:\n        url_obj = url_obj.update_query_dict({"sslmode": "require"})\n    return url_obj\n\n\n@lru_cache\ndef obtener_engine() -> Engine:\n    return create_engine(\n        _url_conexion(),\n        pool_pre_ping=True,     # reconecta si el pooler cerró la conexión\n        pool_size=5,\n        max_overflow=5,\n        connect_args={"connect_timeout": 10},\n    )\n\n\n@lru_cache\ndef _fabrica() -> sessionmaker:\n    return sessionmaker(bind=obtener_engine(), expire_on_commit=False)\n\n\n@contextmanager\ndef sesion() -> Iterator[Session]:\n    """Sesión con commit automático; si algo falla hace rollback y traduce el error."""\n    s: Session = _fabrica()()\n    try:\n        yield s\n        s.commit()\n    except Exception as e:\n        s.rollback()\n        raise traducir_error(e) from e\n    finally:\n        s.close()\n',
    'backend/app/db/modelos.py': '"""Modelos ORM (SQLAlchemy 2.0) de las tablas de la base de datos.\n\nTablas principales del enunciado:\n    Escenario  -> escenarios  (id, nombre, fecha, parametros_entrada)\n    Resultado  -> resultados  (id, escenario_id, algoritmo_utilizado, costo_total,\n                               tiempo_ejecucion_ms, gap_desviacion, matriz_flujos_json)\nTablas de apoyo: Agroempresa, Planta, Ruta, PrecioSombra.\n\nLos campos que calcula la base de datos (parametros_entrada, gap_desviacion,\ncosto_transporte, costo_operativo) se llenan con triggers; después de\ninsertar se hace session.refresh(obj) para leerlos.\n"""\nimport uuid\nfrom datetime import datetime\nfrom decimal import Decimal\nfrom typing import Any\n\nfrom sqlalchemy import Boolean, DateTime, Float, ForeignKey, Integer, Numeric, Text, text\nfrom sqlalchemy.dialects.postgresql import JSONB, UUID\nfrom sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column, relationship\n\n\ndef _num(v: Any) -> Any:\n    """Decimal -> float para responder JSON."""\n    return float(v) if isinstance(v, Decimal) else v\n\n\nclass Base(DeclarativeBase):\n    pass\n\n\nclass Escenario(Base):\n    __tablename__ = "escenarios"\n\n    id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True), primary_key=True,\n                                          server_default=text("gen_random_uuid()"))\n    nombre: Mapped[str] = mapped_column(Text, unique=True)\n    fecha: Mapped[datetime] = mapped_column(DateTime(timezone=True), server_default=text("now()"))\n    descripcion: Mapped[str | None] = mapped_column(Text)\n    parametros_entrada: Mapped[dict] = mapped_column(JSONB, server_default=text("\'{}\'::jsonb"))\n    es_base: Mapped[bool] = mapped_column(Boolean, server_default=text("false"))\n    costo_transporte_km_ton: Mapped[Decimal] = mapped_column(Numeric, server_default=text("1200"))\n    factor_penalizacion_oferta: Mapped[Decimal] = mapped_column(Numeric, server_default=text("1000"))\n    factor_penalizacion_capacidad: Mapped[Decimal] = mapped_column(Numeric, server_default=text("1000"))\n    escenario_origen_id: Mapped[uuid.UUID | None] = mapped_column(\n        UUID(as_uuid=True), ForeignKey("escenarios.id", ondelete="SET NULL"))\n    variaciones: Mapped[dict] = mapped_column(JSONB, server_default=text("\'{}\'::jsonb"))\n    actualizado_en: Mapped[datetime] = mapped_column(DateTime(timezone=True), server_default=text("now()"))\n\n    agroempresas: Mapped[list["Agroempresa"]] = relationship(\n        back_populates="escenario", order_by="Agroempresa.orden",\n        cascade="all, delete-orphan", passive_deletes=True)\n    plantas: Mapped[list["Planta"]] = relationship(\n        back_populates="escenario", order_by="Planta.orden",\n        cascade="all, delete-orphan", passive_deletes=True)\n    resultados: Mapped[list["Resultado"]] = relationship(\n        back_populates="escenario", order_by="Resultado.fecha.desc()",\n        cascade="all, delete-orphan", passive_deletes=True)\n\n    def a_dict(self, incluir_parametros: bool = True) -> dict:\n        d = {\n            "id": str(self.id),\n            "nombre": self.nombre,\n            "fecha": self.fecha,\n            "descripcion": self.descripcion,\n            "es_base": self.es_base,\n            "costo_transporte_km_ton": _num(self.costo_transporte_km_ton),\n            "escenario_origen_id": str(self.escenario_origen_id) if self.escenario_origen_id else None,\n            "variaciones": self.variaciones,\n            "actualizado_en": self.actualizado_en,\n        }\n        if incluir_parametros:\n            d["parametros_entrada"] = self.parametros_entrada\n        return d\n\n\nclass Agroempresa(Base):\n    __tablename__ = "agroempresas"\n\n    id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True), primary_key=True,\n                                          server_default=text("gen_random_uuid()"))\n    escenario_id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True),\n                                                    ForeignKey("escenarios.id", ondelete="CASCADE"))\n    codigo: Mapped[str] = mapped_column(Text)\n    nombre: Mapped[str] = mapped_column(Text)\n    municipio: Mapped[str | None] = mapped_column(Text)\n    sector: Mapped[str | None] = mapped_column(Text)\n    oferta_ton_sem: Mapped[Decimal] = mapped_column(Numeric)\n    orden: Mapped[int] = mapped_column(Integer)\n\n    escenario: Mapped[Escenario] = relationship(back_populates="agroempresas")\n\n\nclass Planta(Base):\n    __tablename__ = "plantas"\n\n    id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True), primary_key=True,\n                                          server_default=text("gen_random_uuid()"))\n    escenario_id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True),\n                                                    ForeignKey("escenarios.id", ondelete="CASCADE"))\n    codigo: Mapped[str] = mapped_column(Text)\n    nombre: Mapped[str] = mapped_column(Text)\n    municipio: Mapped[str | None] = mapped_column(Text)\n    capacidad_maxima_ton_sem: Mapped[Decimal] = mapped_column(Numeric)\n    costo_operativo_ton: Mapped[Decimal] = mapped_column(Numeric)\n    orden: Mapped[int] = mapped_column(Integer)\n\n    escenario: Mapped[Escenario] = relationship(back_populates="plantas")\n\n\nclass Ruta(Base):\n    __tablename__ = "rutas"\n\n    escenario_id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True),\n                                                    ForeignKey("escenarios.id", ondelete="CASCADE"))\n    agroempresa_id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True),\n                                                      ForeignKey("agroempresas.id", ondelete="CASCADE"),\n                                                      primary_key=True)\n    planta_id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True),\n                                                 ForeignKey("plantas.id", ondelete="CASCADE"),\n                                                 primary_key=True)\n    distancia_km: Mapped[Decimal] = mapped_column(Numeric)\n    habilitada: Mapped[bool] = mapped_column(Boolean, server_default=text("true"))\n\n\nclass Resultado(Base):\n    __tablename__ = "resultados"\n\n    id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True), primary_key=True,\n                                          server_default=text("gen_random_uuid()"))\n    escenario_id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True),\n                                                    ForeignKey("escenarios.id", ondelete="CASCADE"))\n    algoritmo_utilizado: Mapped[str] = mapped_column(Text)          # \'Exacto\' | \'Genético\'\n    costo_total: Mapped[Decimal] = mapped_column(Numeric)\n    tiempo_ejecucion_ms: Mapped[float] = mapped_column(Float)\n    gap_desviacion: Mapped[Decimal | None] = mapped_column(Numeric)  # % (lo calcula la BD)\n    matriz_flujos_json: Mapped[dict] = mapped_column(JSONB)\n    costo_transporte: Mapped[Decimal | None] = mapped_column(Numeric)\n    costo_operativo: Mapped[Decimal | None] = mapped_column(Numeric)\n    factible: Mapped[bool | None] = mapped_column(Boolean)\n    parametros_algoritmo: Mapped[dict] = mapped_column(JSONB, server_default=text("\'{}\'::jsonb"))\n    historial_fitness: Mapped[list | None] = mapped_column(JSONB)\n    resultado_exacto_id: Mapped[uuid.UUID | None] = mapped_column(\n        UUID(as_uuid=True), ForeignKey("resultados.id", ondelete="SET NULL"))\n    fecha: Mapped[datetime] = mapped_column(DateTime(timezone=True), server_default=text("now()"))\n\n    escenario: Mapped[Escenario] = relationship(back_populates="resultados")\n    precios_sombra: Mapped[list["PrecioSombra"]] = relationship(\n        back_populates="resultado", cascade="all, delete-orphan", passive_deletes=True)\n\n    def a_dict(self, incluir_matriz: bool = True, incluir_detalle: bool = False) -> dict:\n        d = {\n            "id": str(self.id),\n            "escenario_id": str(self.escenario_id),\n            "escenario": self.escenario.nombre if self.escenario else None,\n            "algoritmo_utilizado": self.algoritmo_utilizado,\n            "costo_total": _num(self.costo_total),\n            "tiempo_ejecucion_ms": self.tiempo_ejecucion_ms,\n            "gap_desviacion": _num(self.gap_desviacion),\n            "costo_transporte": _num(self.costo_transporte),\n            "costo_operativo": _num(self.costo_operativo),\n            "factible": self.factible,\n            "parametros_algoritmo": self.parametros_algoritmo,\n            "resultado_exacto_id": str(self.resultado_exacto_id) if self.resultado_exacto_id else None,\n            "fecha": self.fecha,\n        }\n        if incluir_matriz:\n            d["matriz_flujos_json"] = self.matriz_flujos_json\n        if incluir_detalle:\n            d["historial_fitness"] = self.historial_fitness\n            d["precios_sombra"] = [p.a_dict() for p in self.precios_sombra]\n        return d\n\n\nclass PrecioSombra(Base):\n    __tablename__ = "precios_sombra"\n\n    resultado_id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True),\n                                                    ForeignKey("resultados.id", ondelete="CASCADE"),\n                                                    primary_key=True)\n    tipo: Mapped[str] = mapped_column(Text, primary_key=True)        # \'oferta\' | \'capacidad\'\n    nodo_codigo: Mapped[str] = mapped_column(Text, primary_key=True)\n    valor_dual: Mapped[Decimal] = mapped_column(Numeric)\n    holgura: Mapped[Decimal | None] = mapped_column(Numeric)\n    rango_inferior: Mapped[Decimal | None] = mapped_column(Numeric)\n    rango_superior: Mapped[Decimal | None] = mapped_column(Numeric)\n\n    resultado: Mapped[Resultado] = relationship(back_populates="precios_sombra")\n\n    def a_dict(self) -> dict:\n        return {\n            "tipo": self.tipo,\n            "nodo_codigo": self.nodo_codigo,\n            "valor_dual": _num(self.valor_dual),\n            "holgura": _num(self.holgura),\n            "rango_inferior": _num(self.rango_inferior),\n            "rango_superior": _num(self.rango_superior),\n        }\n',
    'backend/app/services/red/repositorio_bd.py': '"""Consultas y almacenamiento en PostgreSQL (Supabase) con el ORM.\n\nEscenarios\n    listar_escenarios, historial_escenarios, cargar_escenario (formato dataConfig.json),\n    obtener_escenario, guardar_escenario, clonar_escenario, eliminar_escenario\nResultados\n    guardar_resultado, guardar_solucion, listar_resultados, obtener_resultado,\n    historial_comparativo\n\ncargar_escenario() devuelve las mismas claves que dataConfig.json, así que\nrepositorio.a_problema() y genetico.fitness.EvaluadorFitness funcionan sin cambios.\n"""\nimport json\nimport uuid\nfrom decimal import Decimal\nfrom typing import Any\n\nfrom pydantic import BaseModel\nfrom sqlalchemy import func, select, text\nfrom sqlalchemy.orm import selectinload\n\nfrom app.db.modelos import Escenario, PrecioSombra, Resultado\nfrom app.db.sesion import ErrorBaseDatos, EscenarioNoEncontrado, sesion\n\n\ndef _json(valor: Any) -> str:\n    return json.dumps(valor, default=float)\n\n\ndef _fila_a_dict(fila) -> dict:\n    """Fila de una vista -> dict listo para JSON (UUID a texto, Decimal a float)."""\n    d = dict(fila._mapping)\n    for k, v in d.items():\n        if isinstance(v, uuid.UUID):\n            d[k] = str(v)\n        elif isinstance(v, Decimal):\n            d[k] = float(v)\n    return d\n\n\ndef _escenario_por_nombre(s, nombre: str) -> Escenario:\n    esc = s.scalar(select(Escenario).where(Escenario.nombre == nombre))\n    if esc is None:\n        raise EscenarioNoEncontrado(f\'No existe el escenario "{nombre}"\')\n    return esc\n\n\n# ================================================================ escenarios\ndef listar_escenarios() -> list[str]:\n    with sesion() as s:\n        return list(s.scalars(select(Escenario.nombre).order_by(Escenario.nombre)))\n\n\ndef historial_escenarios() -> list[dict]:\n    """Escenarios guardados (más recientes primero) con tamaño de la red, balance y nº de resultados."""\n    with sesion() as s:\n        filas = s.execute(text("select * from public.v_resumen_escenarios order by fecha desc"))\n        return [_fila_a_dict(f) for f in filas]\n\n\ndef cargar_escenario(nombre: str) -> dict:\n    """Escenario completo con el formato de dataConfig.json."""\n    with sesion() as s:\n        return s.scalar(text("select public.obtener_config_escenario(:n)"), {"n": nombre})\n\n\ndef obtener_escenario(nombre: str) -> dict:\n    """Fila de la tabla escenarios: id, nombre, fecha y parametros_entrada (oferta, demanda, costos)."""\n    with sesion() as s:\n        return _escenario_por_nombre(s, nombre).a_dict()\n\n\ndef guardar_escenario(nombre: str, config: dict, descripcion: str | None = None,\n                      es_base: bool = False, reemplazar: bool = False) -> str:\n    """Crea (o con reemplazar=True sobrescribe) un escenario desde el formato dataConfig.json."""\n    with sesion() as s:\n        return str(s.scalar(\n            text("select public.guardar_config_escenario(:n, cast(:c as jsonb), :d, :b, :r)"),\n            {"n": nombre, "c": _json(config), "d": descripcion, "b": es_base, "r": reemplazar}))\n\n\ndef clonar_escenario(origen: str, nuevo: str, variaciones: dict | None = None,\n                     descripcion: str | None = None) -> str:\n    """Copia un escenario sin modificar el original (HU4, HU8)."""\n    with sesion() as s:\n        return str(s.scalar(\n            text("select public.clonar_escenario(:o, :n, cast(:v as jsonb), :d)"),\n            {"o": origen, "n": nuevo, "v": _json(variaciones or {}), "d": descripcion}))\n\n\ndef eliminar_escenario(nombre: str) -> bool:\n    """Borra el escenario con su red y sus resultados. Devuelve False si no existía."""\n    with sesion() as s:\n        esc = s.scalar(select(Escenario).where(Escenario.nombre == nombre))\n        if esc is None:\n            return False\n        s.delete(esc)\n        return True\n\n\n# ================================================================ resultados\ndef guardar_resultado(\n    escenario: str,\n    algoritmo_utilizado: str,\n    costo_total: float,\n    tiempo_ejecucion_ms: float,\n    matriz_flujos: list[list[float]],\n    factible: bool | None = None,\n    parametros_algoritmo: dict | None = None,\n    historial_fitness: list[float] | None = None,\n    costo_transporte: float | None = None,\n    costo_operativo: float | None = None,\n    precios_sombra_oferta: list[float] | None = None,\n    precios_sombra_demanda: list[float] | None = None,\n    rangos_oferta: list[list[float]] | None = None,\n    rangos_demanda: list[list[float]] | None = None,\n) -> dict:\n    """Guarda una ejecución del sistema en la tabla resultados.\n\n    - algoritmo_utilizado: \'Exacto\' o \'Genético\' (también acepta \'exacto\', \'genetico\', \'ag\').\n    - matriz_flujos: xᵢⱼ en el orden de agroempresas (filas) y plantas (columnas) del escenario.\n    - gap_desviacion lo calcula la base de datos contra el último resultado Exacto del escenario.\n    Devuelve el resultado guardado (con gap y desglose de costos ya calculados).\n    """\n    with sesion() as s:\n        esc = _escenario_por_nombre(s, escenario)\n        res = Resultado(\n            escenario_id=esc.id,\n            algoritmo_utilizado=algoritmo_utilizado,\n            costo_total=costo_total,\n            tiempo_ejecucion_ms=tiempo_ejecucion_ms,\n            matriz_flujos_json=[[float(x) for x in fila] for fila in matriz_flujos],\n            factible=factible,\n            parametros_algoritmo=parametros_algoritmo or {},\n            historial_fitness=historial_fitness,\n            costo_transporte=costo_transporte,\n            costo_operativo=costo_operativo,\n        )\n        s.add(res)\n        s.flush()\n        s.refresh(res)   # lee lo que calcularon los triggers (gap, costos, códigos)\n\n        codigos_e = res.matriz_flujos_json["agroempresas"]\n        codigos_p = res.matriz_flujos_json["plantas"]\n        _agregar_duales(s, res, "oferta", codigos_e, precios_sombra_oferta, rangos_oferta)\n        if precios_sombra_demanda:\n            recibido = [sum(fila[j] for fila in matriz_flujos) for j in range(len(codigos_p))]\n            capacidades = esc.parametros_entrada.get("demanda", [])\n            holguras = [float(c) - r for c, r in zip(capacidades, recibido)]\n            _agregar_duales(s, res, "capacidad", codigos_p, precios_sombra_demanda, rangos_demanda, holguras)\n        s.flush()\n        s.refresh(res)\n        return res.a_dict(incluir_detalle=True)\n\n\ndef _agregar_duales(s, res, tipo, codigos, valores, rangos=None, holguras=None):\n    if not valores:\n        return\n    if len(valores) != len(codigos):\n        raise ErrorBaseDatos(f"precios sombra de {tipo}: se esperaban {len(codigos)} valores", 422)\n    for k, (codigo, valor) in enumerate(zip(codigos, valores)):\n        rango = rangos[k] if rangos and k < len(rangos) else [None, None]\n        s.add(PrecioSombra(resultado_id=res.id, tipo=tipo, nodo_codigo=codigo, valor_dual=valor,\n                           holgura=holguras[k] if holguras else None,\n                           rango_inferior=rango[0], rango_superior=rango[1]))\n\n\ndef guardar_solucion(escenario: str, solucion: BaseModel, **extra: Any) -> dict:\n    """Atajo para guardar ResultadoExacto / ResultadoGenetico (schemas/resultados.py).\n\n    Convierte tiempo_s a milisegundos y metodo a algoritmo_utilizado.\n    """\n    d = solucion.model_dump()\n    return guardar_resultado(\n        escenario=escenario,\n        algoritmo_utilizado=d["metodo"],\n        costo_total=d["costo_total"],\n        tiempo_ejecucion_ms=d["tiempo_s"] * 1000,\n        matriz_flujos=d["asignacion"],\n        factible=d.get("factible"),\n        historial_fitness=d.get("historial_fitness") or None,\n        precios_sombra_oferta=d.get("precios_sombra_oferta") or None,\n        precios_sombra_demanda=d.get("precios_sombra_demanda") or None,\n        **extra,\n    )\n\n\ndef listar_resultados(escenario: str | None = None, algoritmo: str | None = None,\n                      limite: int = 50, incluir_matriz: bool = False) -> list[dict]:\n    """Historial de resultados, del más reciente al más antiguo."""\n    with sesion() as s:\n        consulta = select(Resultado).options(selectinload(Resultado.escenario))\n        if escenario:\n            consulta = consulta.where(Resultado.escenario_id == _escenario_por_nombre(s, escenario).id)\n        if algoritmo:\n            alg = "Exacto" if algoritmo.lower().startswith("exact") else "Genético"\n            consulta = consulta.where(Resultado.algoritmo_utilizado == alg)\n        consulta = consulta.order_by(Resultado.fecha.desc()).limit(limite)\n        return [r.a_dict(incluir_matriz=incluir_matriz) for r in s.scalars(consulta)]\n\n\ndef obtener_resultado(id_resultado: str) -> dict | None:\n    try:\n        rid = uuid.UUID(str(id_resultado))\n    except ValueError:\n        return None\n    with sesion() as s:\n        res = s.scalar(select(Resultado).where(Resultado.id == rid)\n                       .options(selectinload(Resultado.escenario), selectinload(Resultado.precios_sombra)))\n        return res.a_dict(incluir_detalle=True) if res else None\n\n\ndef historial_comparativo(escenario: str | None = None) -> list[dict]:\n    """Último Exacto vs. último Genético de cada escenario: costos, tiempos (ms) y gap (%)."""\n    with sesion() as s:\n        sql = "select * from public.v_historial_comparativo"\n        params = {}\n        if escenario:\n            sql += " where escenario = :e"\n            params["e"] = escenario\n        filas = s.execute(text(sql + " order by fecha_ultimo_resultado desc nulls last"), params)\n        return [_fila_a_dict(f) for f in filas]\n\n\ndef contar_resultados() -> int:\n    with sesion() as s:\n        return s.scalar(select(func.count()).select_from(Resultado))\n',
    'backend/app/schemas/persistencia.py': '"""Contratos de la API para guardar y consultar escenarios y resultados en la base de datos."""\nfrom datetime import datetime\nfrom typing import Any\n\nfrom pydantic import BaseModel, Field, field_validator\n\n\n# ------------------------------------------------------------------ escenarios\nclass EscenarioGuardar(BaseModel):\n    nombre: str = Field(..., min_length=1, examples=["Costos +10%"])\n    config: dict[str, Any] = Field(\n        ..., description="Red con el formato de dataConfig.json: parametros_globales, "\n                         "agroempresas, plantas y matriz_distancias_km")\n    descripcion: str | None = None\n    reemplazar: bool = Field(False, description="Sobrescribe si ya existe un escenario con ese nombre")\n\n\nclass EscenarioClonar(BaseModel):\n    nuevo: str = Field(..., min_length=1)\n    variaciones: dict[str, Any] = Field(default_factory=dict,\n                                        examples=[{"variacion_costos_pct": 10}])\n    descripcion: str | None = None\n\n\nclass EscenarioSalida(BaseModel):\n    id: str\n    nombre: str\n    fecha: datetime\n    descripcion: str | None = None\n    es_base: bool\n    costo_transporte_km_ton: float\n    escenario_origen_id: str | None = None\n    variaciones: dict[str, Any] = {}\n    parametros_entrada: dict[str, Any] = Field(\n        default_factory=dict, description="fuentes, plantas, oferta, demanda, costos (cᵢⱼ), distancias_km...")\n    actualizado_en: datetime\n\n\nclass EscenarioResumen(BaseModel):\n    id: str\n    nombre: str\n    fecha: datetime\n    descripcion: str | None = None\n    es_base: bool\n    num_agroempresas: int\n    num_plantas: int\n    num_rutas_habilitadas: int\n    oferta_total: float\n    capacidad_total: float\n    holgura_capacidad: float\n    estado_balance: str\n    num_resultados: int\n    fecha_ultimo_resultado: datetime | None = None\n    escenario_origen_id: str | None = None\n    variaciones: dict[str, Any] = {}\n\n\n# ------------------------------------------------------------------ resultados\nclass ResultadoGuardar(BaseModel):\n    escenario: str = Field(..., description="Nombre del escenario resuelto", examples=["dataConfig"])\n    algoritmo_utilizado: str = Field(..., examples=["Exacto", "Genético"])\n    costo_total: float = Field(..., ge=0)\n    tiempo_ejecucion_ms: float = Field(..., ge=0)\n    matriz_flujos: list[list[float]] = Field(\n        ..., description="xᵢⱼ (t/semana): filas = agroempresas, columnas = plantas, en el orden del escenario")\n    factible: bool | None = None\n    parametros_algoritmo: dict[str, Any] = Field(default_factory=dict)\n    historial_fitness: list[float] | None = None\n    costo_transporte: float | None = None\n    costo_operativo: float | None = None\n    precios_sombra_oferta: list[float] | None = None\n    precios_sombra_demanda: list[float] | None = None\n    rangos_oferta: list[list[float | None]] | None = None\n    rangos_demanda: list[list[float | None]] | None = None\n\n    @field_validator("algoritmo_utilizado")\n    @classmethod\n    def normalizar_algoritmo(cls, v: str) -> str:\n        a = v.strip().lower()\n        if a in {"exacto", "exact", "pl", "lp", "simplex"}:\n            return "Exacto"\n        if a in {"genético", "genetico", "ag", "ga", "algoritmo genético", "algoritmo genetico"}:\n            return "Genético"\n        raise ValueError(\'algoritmo_utilizado debe ser "Exacto" o "Genético"\')\n\n\nclass PrecioSombraSalida(BaseModel):\n    tipo: str\n    nodo_codigo: str\n    valor_dual: float\n    holgura: float | None = None\n    rango_inferior: float | None = None\n    rango_superior: float | None = None\n\n\nclass ResultadoSalida(BaseModel):\n    id: str\n    escenario_id: str\n    escenario: str | None = None\n    algoritmo_utilizado: str\n    costo_total: float\n    tiempo_ejecucion_ms: float\n    gap_desviacion: float | None = Field(None, description="% respecto al último resultado Exacto del escenario")\n    matriz_flujos_json: dict[str, Any] | None = Field(\n        None, description=\'{"agroempresas": [...], "plantas": [...], "toneladas": [[...]]}\')\n    costo_transporte: float | None = None\n    costo_operativo: float | None = None\n    factible: bool | None = None\n    parametros_algoritmo: dict[str, Any] = {}\n    resultado_exacto_id: str | None = None\n    fecha: datetime\n    historial_fitness: list[float] | None = None\n    precios_sombra: list[PrecioSombraSalida] | None = None\n\n\nclass ComparativoFila(BaseModel):\n    escenario_id: str\n    escenario: str\n    fecha_escenario: datetime\n    resultado_exacto_id: str | None = None\n    resultado_genetico_id: str | None = None\n    costo_exacto: float | None = None\n    costo_genetico: float | None = None\n    gap_desviacion: float | None = None\n    tiempo_exacto_ms: float | None = None\n    tiempo_genetico_ms: float | None = None\n    genetico_factible: bool | None = None\n    parametros_ag: dict[str, Any] | None = None\n    fecha_ultimo_resultado: datetime | None = None\n',
    'backend/app/api/routes/dependencias.py': '"""Dependencias compartidas por los endpoints."""\nfrom fastapi import HTTPException\n\nfrom app.core.config import settings\n\n\ndef requiere_bd() -> None:\n    """Los endpoints de historial solo funcionan con la base de datos activa."""\n    if not settings.usa_bd:\n        raise HTTPException(503, "La base de datos no está activa: ponga FUENTE_DATOS=bd en backend/.env")\n',
    'backend/app/api/routes/escenarios.py': '"""Endpoints: historial de escenarios guardados en la base de datos (guardar, consultar, clonar, borrar)."""\nfrom fastapi import APIRouter, Depends, HTTPException\n\nfrom app.api.routes.dependencias import requiere_bd\nfrom app.schemas.persistencia import EscenarioClonar, EscenarioGuardar, EscenarioResumen, EscenarioSalida\nfrom app.services.red import repositorio_bd as bd\n\nrouter = APIRouter(dependencies=[Depends(requiere_bd)])\n\n\n@router.get("", response_model=list[EscenarioResumen])\ndef historial():\n    """Historial de escenarios, del más reciente al más antiguo."""\n    return bd.historial_escenarios()\n\n\n@router.get("/{nombre}", response_model=EscenarioSalida)\ndef obtener(nombre: str):\n    """Escenario con sus parametros_entrada (oferta, demanda y matriz de costos)."""\n    return bd.obtener_escenario(nombre)\n\n\n@router.get("/{nombre}/config")\ndef obtener_config(nombre: str):\n    """Escenario en el formato de dataConfig.json (para editarlo en la web)."""\n    return bd.cargar_escenario(nombre)\n\n\n@router.post("", response_model=EscenarioSalida, status_code=201)\ndef guardar(datos: EscenarioGuardar):\n    """Guarda un escenario nuevo (o lo reemplaza con reemplazar=true)."""\n    bd.guardar_escenario(datos.nombre, datos.config, datos.descripcion, reemplazar=datos.reemplazar)\n    return bd.obtener_escenario(datos.nombre)\n\n\n@router.post("/{nombre}/clonar", response_model=EscenarioSalida, status_code=201)\ndef clonar(nombre: str, datos: EscenarioClonar):\n    """Copia un escenario para simular variaciones sin tocar el original."""\n    bd.clonar_escenario(nombre, datos.nuevo, datos.variaciones, datos.descripcion)\n    return bd.obtener_escenario(datos.nuevo)\n\n\n@router.delete("/{nombre}")\ndef eliminar(nombre: str):\n    """Borra el escenario junto con sus resultados."""\n    if not bd.eliminar_escenario(nombre):\n        raise HTTPException(404, f\'No existe el escenario "{nombre}"\')\n    return {"eliminado": nombre}\n',
    'backend/app/api/routes/resultados.py': '"""Endpoints: guardar cada ejecución (Exacto / Genético) y consultar el historial para el comparativo."""\nfrom fastapi import APIRouter, Depends, HTTPException, Query\n\nfrom app.api.routes.dependencias import requiere_bd\nfrom app.schemas.persistencia import ComparativoFila, ResultadoGuardar, ResultadoSalida\nfrom app.services.red import repositorio_bd as bd\n\nrouter = APIRouter(dependencies=[Depends(requiere_bd)])\n\n\n@router.post("", response_model=ResultadoSalida, status_code=201)\ndef guardar(datos: ResultadoGuardar):\n    """Guarda una ejecución. La base calcula el gap y el desglose transporte/operación."""\n    campos = datos.model_dump(exclude={"matriz_flujos"})\n    return bd.guardar_resultado(matriz_flujos=datos.matriz_flujos, **campos)\n\n\n@router.get("", response_model=list[ResultadoSalida])\ndef historial(\n    escenario: str | None = Query(None, description="Nombre del escenario"),\n    algoritmo: str | None = Query(None, description="Exacto o Genético"),\n    limite: int = Query(50, ge=1, le=500),\n    incluir_matriz: bool = Query(False, description="Incluir matriz_flujos_json en cada fila"),\n):\n    """Historial de resultados, del más reciente al más antiguo."""\n    return bd.listar_resultados(escenario, algoritmo, limite, incluir_matriz)\n\n\n@router.get("/comparativo", response_model=list[ComparativoFila])\ndef comparativo(escenario: str | None = Query(None)):\n    """Último Exacto vs. último Genético de cada escenario: costo, tiempo (ms) y gap (%)."""\n    return bd.historial_comparativo(escenario)\n\n\n@router.get("/{id_resultado}", response_model=ResultadoSalida)\ndef obtener(id_resultado: str):\n    """Un resultado con su matriz de flujos, precios sombra e historial de fitness."""\n    res = bd.obtener_resultado(id_resultado)\n    if res is None:\n        raise HTTPException(404, "No existe ese resultado")\n    return res\n',
    'backend/scripts/__init__.py': '"""Scripts de mantenimiento (siembra de datos, etc.)."""\n',
    'backend/scripts/sembrar_bd.py': '"""Carga en la base de datos los escenarios JSON de backend/data/escenarios/.\n\nUso (desde la carpeta backend/, con el .env configurado):\n\n    python -m scripts.sembrar_bd              # carga los que no existan\n    python -m scripts.sembrar_bd --reemplazar # sobrescribe los existentes\n\nCada archivo <nombre>.json se guarda como el escenario <nombre>;\ndataConfig.json queda marcado como escenario base. Al final se lee cada\nescenario de vuelta y se compara con el archivo para verificar la carga.\n"""\nimport argparse\nimport json\nimport sys\n\nfrom app.db.sesion import ErrorBaseDatos\nfrom app.services.red import repositorio, repositorio_bd as bd\n\nCLAVES_A_VERIFICAR = ("parametros_globales", "plantas", "agroempresas", "matriz_distancias_km")\n\n\ndef main() -> int:\n    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)\n    parser.add_argument("--reemplazar", action="store_true", help="sobrescribe escenarios existentes")\n    args = parser.parse_args()\n\n    try:\n        existentes = set(bd.listar_escenarios())\n    except ErrorBaseDatos as e:\n        print(f"✘ No se pudo consultar la base de datos: {e}")\n        return 1\n\n    archivos = sorted(repositorio.DIR_ESCENARIOS.glob("*.json"))\n    if not archivos:\n        print(f"No hay archivos .json en {repositorio.DIR_ESCENARIOS}")\n        return 1\n\n    errores = 0\n    for ruta in archivos:\n        nombre = ruta.stem\n        config = json.loads(ruta.read_text(encoding="utf-8"))\n        if nombre in existentes and not args.reemplazar:\n            print(f"  = {nombre}: ya existe (use --reemplazar para sobrescribir)")\n            continue\n        try:\n            bd.guardar_escenario(\n                nombre, config,\n                descripcion=config.get("_meta", {}).get("descripcion"),\n                es_base=(nombre == repositorio.ESCENARIO_BASE),\n                reemplazar=args.reemplazar,\n            )\n        except ErrorBaseDatos as e:\n            print(f"  ✘ {nombre}: {e}")\n            errores += 1\n            continue\n\n        en_bd = bd.cargar_escenario(nombre)\n        distintas = [k for k in CLAVES_A_VERIFICAR if en_bd.get(k) != config.get(k)]\n        if distintas:\n            print(f"  ✘ {nombre}: guardado, pero difiere en {distintas}")\n            errores += 1\n        else:\n            print(f"  ✔ {nombre}: guardado y verificado")\n\n    print("\\nHistorial de escenarios en la base de datos:")\n    for r in bd.historial_escenarios():\n        base = " (base)" if r["es_base"] else ""\n        print(f"  {r[\'nombre\']}{base}: {r[\'num_agroempresas\']} agroempresas, {r[\'num_plantas\']} plantas, "\n              f"{r[\'num_rutas_habilitadas\']} rutas · oferta {r[\'oferta_total\']:g} / capacidad "\n              f"{r[\'capacidad_total\']:g} t/sem · {r[\'estado_balance\']} · {r[\'num_resultados\']} resultados")\n    return 1 if errores else 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n',
    'backend/tests/test_bd.py': '"""Pruebas de la base de datos: guardar una ejecución y recuperar el historial.\n\nSe saltan si FUENTE_DATOS no es "bd" en backend/.env, para que `pytest`\nsiga funcionando sin base de datos. Para ejecutarlas:\n\n    python -m pytest tests/test_bd.py -v\n\nTrabajan sobre escenarios temporales "_prueba_pytest*" que se borran al\nfinal; no tocan el escenario base.\n"""\nimport json\n\nimport pytest\nfrom fastapi.testclient import TestClient\n\nfrom app.core.config import settings\nfrom app.main import app\nfrom app.services.red import repositorio\n\npytestmark = pytest.mark.skipif(not settings.usa_bd, reason="FUENTE_DATOS != bd")\n\nNOMBRE = "_prueba_pytest"\nCOPIA = "_prueba_pytest_copia"\ncliente = TestClient(app)\n\n\ndef leer_json_base() -> dict:\n    with open(repositorio.DIR_ESCENARIOS / f"{repositorio.ESCENARIO_BASE}.json", encoding="utf-8") as f:\n        return json.load(f)\n\n\ndef asignacion_voraz(problema):\n    """Asignación factible sencilla: cada empresa a la planta más barata con capacidad."""\n    cap = list(problema.demanda)\n    x = [[0.0] * len(cap) for _ in problema.oferta]\n    for i, oferta in enumerate(problema.oferta):\n        for j in sorted(range(len(cap)), key=lambda j: problema.costos[i][j]):\n            t = min(oferta, cap[j]); x[i][j] += t; cap[j] -= t; oferta -= t\n    costo = sum(problema.costos[i][j] * x[i][j] for i in range(len(x)) for j in range(len(cap)))\n    return x, costo\n\n\n@pytest.fixture(scope="module", autouse=True)\ndef escenario_temporal():\n    for n in (NOMBRE, COPIA):\n        cliente.delete(f"/api/escenarios/{n}")\n    r = cliente.post("/api/escenarios", json={"nombre": NOMBRE, "config": leer_json_base(),\n                                              "descripcion": "temporal de pytest"})\n    assert r.status_code == 201, r.text\n    yield r.json()\n    for n in (NOMBRE, COPIA):\n        cliente.delete(f"/api/escenarios/{n}")\n\n\ndef test_tabla_escenarios_tiene_id_nombre_fecha_y_parametros(escenario_temporal):\n    e = escenario_temporal\n    assert e["id"] and e["nombre"] == NOMBRE and e["fecha"]\n    p = e["parametros_entrada"]\n    base = leer_json_base()\n    assert p["oferta"] == [a["oferta_ton_sem"] for a in base["agroempresas"]]\n    assert p["demanda"] == [pl["capacidad_maxima_ton_sem"] for pl in base["plantas"]]\n    # costos = matriz cᵢⱼ que usan los solucionadores\n    assert p["costos"] == repositorio.a_problema(base).costos\n\n\ndef test_mismo_formato_que_dataconfig():\n    base = leer_json_base()\n    en_bd = cliente.get(f"/api/escenarios/{NOMBRE}/config").json()\n    for clave in ("parametros_globales", "plantas", "agroempresas", "matriz_distancias_km"):\n        assert en_bd[clave] == base[clave], clave\n\n\ndef test_guardar_ejecucion_y_recuperar_historial():\n    problema = repositorio.a_problema(leer_json_base())\n    x, costo = asignacion_voraz(problema)\n\n    r_ag = cliente.post("/api/resultados", json={\n        "escenario": NOMBRE, "algoritmo_utilizado": "genetico", "costo_total": costo * 1.05,\n        "tiempo_ejecucion_ms": 850.5, "matriz_flujos": x, "factible": True,\n        "parametros_algoritmo": {"poblacion": 100, "generaciones": 500}})\n    assert r_ag.status_code == 201, r_ag.text\n    ag = r_ag.json()\n    assert ag["algoritmo_utilizado"] == "Genético"\n    assert ag["gap_desviacion"] is None            # aún no hay resultado exacto\n\n    r_ex = cliente.post("/api/resultados", json={\n        "escenario": NOMBRE, "algoritmo_utilizado": "Exacto", "costo_total": costo,\n        "tiempo_ejecucion_ms": 12.3, "matriz_flujos": x, "factible": True,\n        "precios_sombra_oferta": [0.0] * len(problema.oferta),\n        "precios_sombra_demanda": [0.0] * len(problema.demanda)})\n    assert r_ex.status_code == 201, r_ex.text\n    ex = r_ex.json()\n    assert ex["gap_desviacion"] == 0\n    assert ex["costo_transporte"] + ex["costo_operativo"] == pytest.approx(costo)\n    assert ex["matriz_flujos_json"]["toneladas"] == x\n    assert ex["matriz_flujos_json"]["agroempresas"][0] == "E01"\n    assert len(ex["precios_sombra"]) == len(problema.oferta) + len(problema.demanda)\n\n    # al guardar el exacto se completa el gap del genético\n    ag = cliente.get(f"/api/resultados/{ag[\'id\']}").json()\n    assert ag["gap_desviacion"] == pytest.approx(5.0)\n    assert ag["resultado_exacto_id"] == ex["id"]\n\n    historial = cliente.get("/api/resultados", params={"escenario": NOMBRE}).json()\n    assert [h["algoritmo_utilizado"] for h in historial] == ["Exacto", "Genético"]\n\n    comp = cliente.get("/api/resultados/comparativo", params={"escenario": NOMBRE}).json()\n    assert len(comp) == 1\n    assert comp[0]["gap_desviacion"] == pytest.approx(5.0)\n    assert comp[0]["tiempo_exacto_ms"] == pytest.approx(12.3)\n\n    escenarios = cliente.get("/api/escenarios").json()\n    fila = next(e for e in escenarios if e["nombre"] == NOMBRE)\n    assert fila["num_resultados"] == 2\n\n\ndef test_validaciones():\n    malo = cliente.post("/api/resultados", json={\n        "escenario": NOMBRE, "algoritmo_utilizado": "Exacto", "costo_total": 1,\n        "tiempo_ejecucion_ms": 1, "matriz_flujos": [[1, 2]]})\n    assert malo.status_code == 422 and "matriz_flujos_json" in malo.text\n\n    alg = cliente.post("/api/resultados", json={\n        "escenario": NOMBRE, "algoritmo_utilizado": "Otro", "costo_total": 1,\n        "tiempo_ejecucion_ms": 1, "matriz_flujos": [[0]]})\n    assert alg.status_code == 422\n\n    assert cliente.get("/api/escenarios/no-existe").status_code == 404\n    dup = cliente.post("/api/escenarios", json={"nombre": NOMBRE, "config": leer_json_base()})\n    assert dup.status_code == 409\n\n\ndef test_clonar_no_modifica_original():\n    r = cliente.post(f"/api/escenarios/{NOMBRE}/clonar",\n                     json={"nuevo": COPIA, "variaciones": {"variacion_costos_pct": 10}})\n    assert r.status_code == 201, r.text\n    copia = cliente.get(f"/api/escenarios/{COPIA}/config").json()\n    copia["agroempresas"][0]["oferta_ton_sem"] = 999\n    r = cliente.post("/api/escenarios", json={"nombre": COPIA, "config": copia, "reemplazar": True})\n    assert r.json()["parametros_entrada"]["oferta"][0] == 999\n    original = cliente.get(f"/api/escenarios/{NOMBRE}").json()\n    assert original["parametros_entrada"]["oferta"][0] != 999\n',
    'backend/.env.example': 'APP_NOMBRE=EcoResiduos API\nCORS_ORIGENES=http://localhost:5173\n\n# --- Base de datos ---\n# json -> lee backend/data/escenarios/*.json (sin base de datos)\n# bd   -> PostgreSQL de Supabase con SQLAlchemy\nFUENTE_DATOS=json\n# Supabase > botón "Connect" > "Session pooler" (copiar la URI completa)\nDATABASE_URL=postgresql://postgres.xxxxxxxxxxxxxxxxxxxx:[YOUR-PASSWORD]@aws-1-us-east-1.pooler.supabase.com:5432/postgres\n# Contraseña de la base de datos (la que pusieron al crear el proyecto).\n# Va aquí y NO dentro de DATABASE_URL: así no hay que codificar caracteres especiales.\n# Solo en backend/.env; nunca en .env.example ni en GitHub.\nDATABASE_PASSWORD=\n',
    'frontend/src/api/historial.js': "// Historial en base de datos: escenarios guardados y resultados de cada ejecución.\n// Requiere FUENTE_DATOS=bd en backend/.env (si no, el backend responde 503).\nimport { peticion } from './cliente.js'\n\nconst q = (params) => {\n  const limpio = Object.fromEntries(Object.entries(params).filter(([, v]) => v !== undefined && v !== null && v !== ''))\n  const s = new URLSearchParams(limpio).toString()\n  return s ? `?${s}` : ''\n}\nconst n = (nombre) => encodeURIComponent(nombre)\n\n// ---------------------------------------------------------------- escenarios\nexport const listarHistorialEscenarios = () => peticion('/escenarios')\nexport const obtenerEscenarioGuardado = (nombre) => peticion(`/escenarios/${n(nombre)}`)\nexport const obtenerConfigEscenario = (nombre) => peticion(`/escenarios/${n(nombre)}/config`)\n\n// datos = { nombre, config (formato dataConfig.json), descripcion?, reemplazar? }\nexport const guardarEscenario = (datos) =>\n  peticion('/escenarios', { metodo: 'POST', cuerpo: datos })\n\n// datos = { nuevo, variaciones?, descripcion? }\nexport const clonarEscenario = (nombre, datos) =>\n  peticion(`/escenarios/${n(nombre)}/clonar`, { metodo: 'POST', cuerpo: datos })\n\nexport const eliminarEscenario = (nombre) =>\n  peticion(`/escenarios/${n(nombre)}`, { metodo: 'DELETE' })\n\n// ---------------------------------------------------------------- resultados\n// datos = { escenario, algoritmo_utilizado: 'Exacto' | 'Genético', costo_total,\n//           tiempo_ejecucion_ms, matriz_flujos: [[...]], factible?, parametros_algoritmo?,\n//           historial_fitness?, precios_sombra_oferta?, precios_sombra_demanda? }\nexport const guardarResultado = (datos) =>\n  peticion('/resultados', { metodo: 'POST', cuerpo: datos })\n\n// filtros = { escenario?, algoritmo?, limite?, incluir_matriz? }\nexport const listarResultados = (filtros = {}) => peticion(`/resultados${q(filtros)}`)\nexport const obtenerResultado = (id) => peticion(`/resultados/${id}`)\n\n// último Exacto vs. último Genético por escenario (costo, tiempo y gap)\nexport const obtenerComparativo = (escenario) => peticion(`/resultados/comparativo${q({ escenario })}`)\n\n// Atajo: convierte la respuesta de /exacto/resolver o /genetico/... y la guarda.\nexport const guardarSolucion = (escenario, solucion, extra = {}) =>\n  guardarResultado({\n    escenario,\n    algoritmo_utilizado: solucion.metodo,\n    costo_total: solucion.costo_total,\n    tiempo_ejecucion_ms: solucion.tiempo_s * 1000,\n    matriz_flujos: solucion.asignacion,\n    factible: solucion.factible,\n    historial_fitness: solucion.historial_fitness,\n    precios_sombra_oferta: solucion.precios_sombra_oferta,\n    precios_sombra_demanda: solucion.precios_sombra_demanda,\n    ...extra,\n  })\n",
    'docs/base-datos/GUIA_BASE_DATOS.md': '# Base de datos PostgreSQL (Supabase) — guía paso a paso\n\nBase de datos para guardar las simulaciones del sistema de optimización de\nEcoResiduos del Llano S.A.S.\n\n```\nWeb UI (React)  ──HTTP──►  FastAPI  ──SQLAlchemy (ORM)──►  PostgreSQL en Supabase\n                              │\n                              └─ con FUENTE_DATOS=json sigue usando data/escenarios/*.json\n```\n\n## Cómo se cumple el requerimiento\n\n| Requerimiento | Dónde está |\n|---|---|\n| Tabla **Escenarios**: id, nombre, fecha, parámetros de entrada (oferta, demanda, costos) | `escenarios.id`, `nombre`, `fecha`, `parametros_entrada` (JSON con `oferta`, `demanda`, `costos` cᵢⱼ, `distancias_km`...) |\n| Tabla **Resultados**: id, escenario_id, algoritmo_utilizado ("Exacto" \\| "Genético"), costo_total, tiempo_ejecucion_ms, gap_desviacion, matriz_flujos_json | Tabla `resultados` con esas mismas columnas |\n| Conexión / ORM en Python | `app/db/sesion.py` (conexión) y `app/db/modelos.py` (modelos `Escenario`, `Resultado`, ...) con SQLAlchemy 2.0 |\n| Consultar y almacenar desde la Web UI | Endpoints `/api/escenarios` y `/api/resultados` + `frontend/src/api/historial.js` |\n| Guardar una ejecución y recuperar el historial para el análisis comparativo | `POST /api/resultados`, `GET /api/resultados`, `GET /api/escenarios`, `GET /api/resultados/comparativo` (probado en `tests/test_bd.py`) |\n\n### Tabla `escenarios`\n\n| Columna | Tipo | Descripción |\n|---|---|---|\n| `id` | uuid | Identificador |\n| `nombre` | text, único | Nombre del escenario (p. ej. `dataConfig`, `Costos +10%`) |\n| `fecha` | timestamptz | Fecha de creación |\n| `parametros_entrada` | jsonb | `{"fuentes", "plantas", "oferta", "demanda", "costos", "distancias_km", "costo_operativo", "costo_transporte_km_ton", "oferta_total", "capacidad_total"}` |\n| `descripcion`, `es_base`, `costo_transporte_km_ton`, `variaciones`, `escenario_origen_id` | | Datos adicionales |\n\n`parametros_entrada` **se calcula solo** a partir de las tablas `agroempresas`, `plantas` y\n`rutas`, así que nunca queda desactualizado. Se edita la red, no el JSON.\n\n### Tabla `resultados`\n\n| Columna | Tipo | Descripción |\n|---|---|---|\n| `id` | uuid | Identificador |\n| `escenario_id` | uuid → escenarios | Escenario resuelto |\n| `algoritmo_utilizado` | text | `\'Exacto\'` o `\'Genético\'` |\n| `costo_total` | numeric | Z (COP/semana) |\n| `tiempo_ejecucion_ms` | double | Tiempo de cómputo en milisegundos |\n| `gap_desviacion` | numeric | % = (Z_AG − Z_exacto) / Z_exacto × 100. Es 0 para Exacto. **Lo calcula la base** contra el último Exacto del mismo escenario. |\n| `matriz_flujos_json` | jsonb | `{"agroempresas": ["E01", ...], "plantas": ["P1", ...], "toneladas": [[...]]}` |\n| `costo_transporte`, `costo_operativo` | numeric | Desglose de Z (lo calcula la base) |\n| `factible`, `parametros_algoritmo`, `historial_fitness`, `resultado_exacto_id` | | Datos adicionales para el informe |\n\nTablas de apoyo: `agroempresas`, `plantas` y `rutas` guardan la red editable G = (V, E), y\n`precios_sombra` guarda los duales de cada resultado exacto.\n\n---\n\n## Paso 1. Instalar los archivos en el repo\n\nCopien `instalar_bd.py` en la **carpeta general del repo** (donde están `backend/` y\n`frontend/`) y ejecútenlo:\n\n```powershell\ncd C:\\Users\\Lenovo\\Documents\\GitHub\\Optimizacion-Red-Logistica-Recepcion-y-Procesamiento-Residuos-Agropecuarios\npython instalar_bd.py\n```\n\nEl instalador crea o actualiza todos los archivos, borra los de la versión anterior con\n`supabase-py` y guarda una copia `*.antes_bd.bak` de cada archivo que reemplaza. Al final\nmuestra la lista de lo que hizo. Revisen que todo esté bien, borren los `.bak` y luego\nborren `instalar_bd.py`.\n\n## Paso 2. Crear las tablas en Supabase\n\nEn Supabase: **SQL Editor → New query**.\n\n1. **Solo esta vez**, porque ya existían tablas de la versión anterior: abran\n   `supabase/reiniciar_base_datos.sql`, copien todo, péguenlo y den **Run**.\n   Si Supabase avisa de "operaciones destructivas", acepten: borra las tablas viejas.\n2. En otra consulta, peguen `supabase/crear_base_datos_ecoresiduos.sql` completo y den **Run**.\n   Debe salir `Success. No rows returned`.\n\nComprobación en **Table Editor**: deben aparecer `escenarios`, `resultados`,\n`agroempresas`, `plantas`, `rutas` y `precios_sombra`.\n\n> `crear_base_datos_ecoresiduos.sql` se puede volver a ejecutar sin perder datos.\n> `reiniciar_base_datos.sql` **borra todo**: no lo vuelvan a usar.\n\n## Paso 3. Copiar la cadena de conexión\n\n1. En Supabase, botón **Connect** (arriba, en la barra del proyecto).\n2. Pestaña **Connection String**, tipo **URI**, método **Session pooler**.\n   Usen el *Session pooler* y no el *Direct connection*, que no funciona en redes solo IPv4.\n3. Copien la URI. Se ve así:\n   ```\n   postgresql://postgres.upfcdctfgcyncgpcbcjt:[YOUR-PASSWORD]@aws-1-us-east-1.pooler.supabase.com:5432/postgres\n   ```\n4. La contraseña es la que pusieron al crear el proyecto. Si no la recuerdan:\n   **Project Settings → Database → Reset database password**.\n\n## Paso 4. Configurar `backend/.env`\n\n```env\nFUENTE_DATOS=bd\nDATABASE_URL=postgresql://postgres.upfcdctfgcyncgpcbcjt:[YOUR-PASSWORD]@aws-1-us-east-1.pooler.supabase.com:5432/postgres\nDATABASE_PASSWORD=la_contraseña_de_la_base\n```\n\n- Peguen la URI **tal cual**, con `[YOUR-PASSWORD]` incluido. La contraseña va aparte, en\n  `DATABASE_PASSWORD`, y el backend la inserta solo. Así no hay que codificar caracteres como `@` o `#`.\n- Las líneas viejas `SUPABASE_URL` y `SUPABASE_SECRET_KEY` ya no se usan y se pueden borrar.\n- El `.env` **nunca** se sube a GitHub. El `.env.example` sí se sube, pero sin contraseña.\n\n## Paso 5. Instalar dependencias\n\n```powershell\ncd backend\npython -m pip install -r requirements.txt\n```\n\nSe agregan `sqlalchemy==2.0.57` y `psycopg2-binary==2.9.13`, y se quita `supabase`.\nSi quieren desinstalarlo: `python -m pip uninstall supabase`.\n\n## Paso 6. Cargar el caso base\n\n```powershell\npython -m scripts.sembrar_bd\n```\n\nSalida esperada:\n\n```\n  ✔ dataConfig: guardado y verificado\n\nHistorial de escenarios en la base de datos:\n  dataConfig (base): 10 agroempresas, 4 plantas, 40 rutas · oferta 1540 / capacidad 1700 t/sem · capacidad_sobrante · 0 resultados\n```\n\nSi después cambian `dataConfig.json`, se recarga con `python -m scripts.sembrar_bd --reemplazar`.\n\n## Paso 7. Probar\n\n```powershell\npython -m pytest tests/test_bd.py -v\n```\n\nDeben pasar las 5 pruebas:\n- La tabla de escenarios tiene id, nombre, fecha y parámetros.\n- El escenario tiene el mismo formato que `dataConfig.json`.\n- Una ejecución se guarda y el historial se recupera.\n- Las validaciones rechazan datos incorrectos.\n- Clonar un escenario no modifica el original.\n\nLas pruebas usan escenarios temporales y los borran al final.\n\n## Paso 8. Probar los endpoints\n\n```powershell\npython -m uvicorn app.main:app --reload\n```\n\nAbran **http://localhost:8000/docs**. Ahí aparecen las secciones *Historial de escenarios (BD)*\ny *Resultados (BD)*, y cada endpoint se puede probar con **Try it out**:\n\n| Método | Ruta | Para qué |\n|---|---|---|\n| GET | `/api/escenarios` | Historial de escenarios (más reciente primero) |\n| GET | `/api/escenarios/{nombre}` | Un escenario con sus `parametros_entrada` |\n| GET | `/api/escenarios/{nombre}/config` | El escenario en formato `dataConfig.json` |\n| POST | `/api/escenarios` | Guardar un escenario `{nombre, config, descripcion?, reemplazar?}` |\n| POST | `/api/escenarios/{nombre}/clonar` | Copiar `{nuevo, variaciones?}` |\n| DELETE | `/api/escenarios/{nombre}` | Borrar un escenario y sus resultados |\n| POST | `/api/resultados` | **Guardar una ejecución** |\n| GET | `/api/resultados?escenario=&algoritmo=` | **Historial de resultados** |\n| GET | `/api/resultados/{id}` | Un resultado con matriz, precios sombra y fitness |\n| GET | `/api/resultados/comparativo?escenario=` | **Último Exacto vs. último Genético: costo, tiempo y gap** |\n\nEjemplo de cuerpo para `POST /api/resultados`:\n\n```json\n{\n  "escenario": "dataConfig",\n  "algoritmo_utilizado": "Genético",\n  "costo_total": 152344000,\n  "tiempo_ejecucion_ms": 850.5,\n  "matriz_flujos": [[0,120,0,0],[250,0,0,0],[90,0,0,0],[0,0,180,0],[0,0,0,210],\n                    [0,0,160,0],[110,0,0,0],[0,0,110,30],[0,80,0,0],[50,150,0,0]],\n  "factible": true,\n  "parametros_algoritmo": {"poblacion": 100, "generaciones": 500, "tasa_cruce": 0.8}\n}\n```\n\n---\n\n## Uso desde la Web UI (React)\n\n`frontend/src/api/historial.js` trae las funciones listas:\n\n```js\nimport { resolverExacto } from \'../api/exacto.js\'\nimport { guardarSolucion, listarResultados, obtenerComparativo,\n         listarHistorialEscenarios } from \'../api/historial.js\'\n\n// después de resolver, guardar la ejecución\nconst solucion = await resolverExacto(problema)\nawait guardarSolucion(\'dataConfig\', solucion)          // convierte tiempo_s a ms\n\n// historial para la página Comparativo\nconst escenarios = await listarHistorialEscenarios()\nconst resultados = await listarResultados({ escenario: \'dataConfig\' })\nconst comparativo = await obtenerComparativo(\'dataConfig\')   // gap_desviacion, tiempos...\n```\n\n## Uso desde Python\n\n```python\nfrom app.services.red import repositorio, repositorio_bd as bd\n\nproblema = repositorio.a_problema(repositorio.cargar_escenario("dataConfig"))\nsolucion = solver.resolver(problema)                 # ResultadoExacto\nbd.guardar_solucion("dataConfig", solucion, parametros_algoritmo={"solver": "pulp"})\n\nbd.listar_resultados("dataConfig")                   # historial\nbd.historial_comparativo()                           # Exacto vs Genético por escenario\nbd.clonar_escenario("dataConfig", "Costos +10%", {"variacion_costos_pct": 10})\n```\n\nDirectamente con el ORM:\n\n```python\nfrom sqlalchemy import select\nfrom app.db.sesion import sesion\nfrom app.db.modelos import Escenario, Resultado\n\nwith sesion() as s:\n    esc = s.scalar(select(Escenario).where(Escenario.nombre == "dataConfig"))\n    print(esc.fecha, esc.parametros_entrada["oferta"])\n    for r in esc.resultados:                         # ordenados del más reciente al más antiguo\n        print(r.algoritmo_utilizado, r.costo_total, r.tiempo_ejecucion_ms, r.gap_desviacion)\n```\n\nReglas:\n- `matriz_flujos` va en el orden de `agroempresas` (filas) y `plantas` (columnas) del escenario.\n- Los arreglos de NumPy se convierten con `.tolist()`.\n- El gap de un Genético se calcula contra el último Exacto del escenario. Si el Genético se\n  guarda primero, el gap queda vacío y se completa solo cuando se guarda el Exacto.\n\n## Errores comunes\n\n| Mensaje | Causa |\n|---|---|\n| `Falta DATABASE_URL en backend/.env` | El `.env` no está en `backend/`, tiene otro nombre o falta la línea |\n| `password authentication failed` | La contraseña en `DATABASE_PASSWORD` está mal; restablézcanla en Supabase |\n| `could not translate host name` / `timeout` | Copiaron *Direct connection*; usen **Session pooler** |\n| `relation "escenarios" does not exist` | Falta el Paso 2 |\n| `No module named \'sqlalchemy\'` | Falta el Paso 5 |\n| `503 La base de datos no está activa` | `FUENTE_DATOS` no es `bd` |\n',
}

VIEJOS = [
    'backend/app/db/supabase_cliente.py',
    'backend/app/services/red/repositorio_supabase.py',
    'backend/scripts/sembrar_supabase.py',
    'backend/tests/test_supabase.py',
    'docs/base-datos/GUIA_SUPABASE.md',
]


def leer(ruta: Path) -> str:
    return ruta.read_text(encoding='utf-8')


def escribir(rel: str, contenido: str) -> None:
    ruta = RAIZ / rel
    if ruta.exists():
        actual = leer(ruta)
        if actual == contenido:
            hechos.append(f'  = {rel} (sin cambios)')
            return
        respaldo = ruta.with_name(ruta.name + '.antes_bd.bak')
        respaldo.write_text(actual, encoding='utf-8')
        accion = 'actualizado (copia en .antes_bd.bak)'
    else:
        ruta.parent.mkdir(parents=True, exist_ok=True)
        accion = 'creado'
    ruta.write_text(contenido, encoding='utf-8', newline='\n')
    hechos.append(f'  + {rel}: {accion}')


def parchear_main() -> None:
    rel = 'backend/app/main.py'
    ruta = RAIZ / rel
    s = leer(ruta)
    if 'resultados.router' in s:
        hechos.append(f'  = {rel} (ya tenía los endpoints)')
        return
    original = s
    s = s.replace('from fastapi import FastAPI\n',
                  'from fastapi import FastAPI, Request\n', 1)
    if 'from fastapi.responses import JSONResponse' not in s:
        s = s.replace('from fastapi.middleware.cors import CORSMiddleware\n',
                      'from fastapi.middleware.cors import CORSMiddleware\nfrom fastapi.responses import JSONResponse\n', 1)
    s, n = re.subn(r'from app\.api\.routes import ([^\n]+)\n',
                   lambda m: f'from app.api.routes import {m.group(1).rstrip()}, escenarios, resultados\n'
                             'from app.db.sesion import ErrorBaseDatos\n', s, count=1)
    m = list(re.finditer(r'app\.include_router\([^\n]+\)\n', s))
    if n == 0 or not m or 'Request' not in s:
        avisos.append(f'No pude modificar {rel} automáticamente; agréguelo a mano (ver GUIA_BASE_DATOS.md).')
        return
    fin = m[-1].end()
    bloque = (
        'app.include_router(escenarios.router, prefix="/api/escenarios", tags=["Historial de escenarios (BD)"])\n'
        'app.include_router(resultados.router, prefix="/api/resultados", tags=["Resultados (BD)"])\n'
        '\n\n'
        '@app.exception_handler(ErrorBaseDatos)\n'
        'def error_base_datos(_: Request, e: ErrorBaseDatos):\n'
        '    """Errores de la base de datos -> respuesta JSON con el mensaje de PostgreSQL."""\n'
        '    return JSONResponse(status_code=e.codigo_http, content={"detail": e.mensaje})\n'
    )
    s = s[:fin] + bloque + s[fin:]
    ruta.with_name(ruta.name + '.antes_bd.bak').write_text(original, encoding='utf-8')
    ruta.write_text(s, encoding='utf-8', newline='\n')
    hechos.append(f'  + {rel}: endpoints /api/escenarios y /api/resultados registrados (copia en .antes_bd.bak)')


NUEVAS_FUNCIONES = '''def listar_escenarios() -> list[str]:
    if settings.usa_bd:
        from app.services.red import repositorio_bd
        return repositorio_bd.listar_escenarios()
    return sorted(p.stem for p in DIR_ESCENARIOS.glob("*.json"))


def cargar_escenario(nombre: str = ESCENARIO_BASE) -> dict:
    """Devuelve el escenario con el formato de dataConfig.json.

    Con FUENTE_DATOS=bd lo lee de PostgreSQL (mismas claves);
    si no, lo lee del archivo en disco.
    """
    if settings.usa_bd:
        from app.services.red import repositorio_bd
        return repositorio_bd.cargar_escenario(nombre)
    with open(DIR_ESCENARIOS / f"{nombre}.json", encoding="utf-8") as f:
        return json.load(f)


'''


def parchear_repositorio() -> None:
    rel = 'backend/app/services/red/repositorio.py'
    ruta = RAIZ / rel
    s = leer(ruta)
    original = s
    if 'repositorio_bd.cargar_escenario' in s and 'repositorio_supabase' not in s:
        hechos.append(f'  = {rel} (ya leía de la base de datos)')
        return
    inicio = s.find('def listar_escenarios(')
    fin = s.find('def calcular_costos(')
    if inicio < 0 or fin < 0 or fin < inicio:
        avisos.append(f'No pude modificar {rel} automáticamente; reemplace listar_escenarios y '
                      'cargar_escenario a mano (ver GUIA_BASE_DATOS.md).')
        return
    s = s[:inicio] + NUEVAS_FUNCIONES + s[fin:]
    if 'from app.core.config import settings' not in s:
        s = s.replace('from app.schemas.red import ProblemaTransporte',
                      'from app.core.config import settings\nfrom app.schemas.red import ProblemaTransporte', 1)
    ruta.with_name(ruta.name + '.antes_bd.bak').write_text(original, encoding='utf-8')
    ruta.write_text(s, encoding='utf-8', newline='\n')
    hechos.append(f'  + {rel}: lee de la base con FUENTE_DATOS=bd (copia en .antes_bd.bak)')


def parchear_requirements() -> None:
    rel = 'backend/requirements.txt'
    ruta = RAIZ / rel
    lineas = leer(ruta).splitlines()
    nuevas = [l for l in lineas if not l.strip().lower().startswith('supabase')]
    for paquete in ('sqlalchemy==2.0.57', 'psycopg2-binary==2.9.13'):
        nombre = paquete.split('==')[0]
        if not any(l.strip().lower().startswith(nombre) for l in nuevas):
            nuevas.append(paquete)
    if nuevas == lineas:
        hechos.append(f'  = {rel} (sin cambios)')
        return
    ruta.write_text('\n'.join(nuevas) + '\n', encoding='utf-8', newline='\n')
    hechos.append(f'  + {rel}: agrega sqlalchemy y psycopg2-binary, quita supabase')


def actualizar_env() -> None:
    ruta = RAIZ / 'backend/.env'
    if not ruta.exists():
        avisos.append('No existe backend/.env: créelo copiando backend/.env.example y complete '
                      'DATABASE_URL y DATABASE_PASSWORD (Paso 4 de la guía).')
        return
    texto = leer(ruta)
    lineas = texto.splitlines()
    cambios = []
    if re.search(r'^FUENTE_DATOS=', texto, re.M):
        lineas = ['FUENTE_DATOS=bd' if l.startswith('FUENTE_DATOS=') else l for l in lineas]
        cambios.append('FUENTE_DATOS=bd')
    else:
        lineas.append('FUENTE_DATOS=bd')
        cambios.append('FUENTE_DATOS=bd')
    for clave in ('DATABASE_URL', 'DATABASE_PASSWORD'):
        if not re.search(rf'^{clave}=', texto, re.M):
            lineas.append(f'{clave}=')
            cambios.append(f'{clave}= (vacía: complétela)')
    ruta.write_text('\n'.join(lineas) + '\n', encoding='utf-8', newline='\n')
    hechos.append(f'  + backend/.env: {", ".join(cambios)}')
    if re.search(r'^DATABASE_(URL|PASSWORD)=\s*$', '\n'.join(lineas), re.M):
        avisos.append('Complete DATABASE_URL y DATABASE_PASSWORD en backend/.env (Paso 3 y 4 de la guía).')
    if 'SUPABASE_SECRET_KEY=' in texto:
        avisos.append('backend/.env todavía tiene SUPABASE_URL / SUPABASE_SECRET_KEY: ya no se usan, puede borrarlas.')


def main() -> int:
    if not (RAIZ / 'backend').is_dir() or not (RAIZ / 'frontend').is_dir():
        print('✘ Ejecute este archivo desde la carpeta general del repo (donde están backend/ y frontend/).')
        print(f'  Carpeta actual: {RAIZ}')
        return 1

    for rel, contenido in ARCHIVOS.items():
        escribir(rel, contenido)
    parchear_main()
    parchear_repositorio()
    parchear_requirements()
    for rel in VIEJOS:
        ruta = RAIZ / rel
        if ruta.exists():
            ruta.unlink()
            hechos.append(f'  - {rel}: borrado (versión anterior)')
    actualizar_env()

    print('Instalación de la base de datos\n')
    print('\n'.join(hechos))
    if avisos:
        print('\nPendiente:')
        for a in avisos:
            print(f'  ! {a}')
    print('\nSiguiente: Paso 2 de docs/base-datos/GUIA_BASE_DATOS.md (ejecutar el SQL en Supabase).')
    return 0


if __name__ == '__main__':
    sys.exit(main())